class Inventory:
    def __init__(self):
        self.items = {}

    def add_item(self, item_name, quantity):
        """
        Adds the specified quantity of the item to the inventory.

        :param item_name: The name of the item to add.
        :param quantity: The quantity of the item to add.
        """
        if item_name in self.items:
            self.items[item_name] += quantity
        else:
            self.items[item_name] = quantity

    def remove_item(self, item_name, quantity):
        """
        Removes the specified quantity of the item from the inventory.
        If the quantity to remove exceeds the available stock, all units of the item are removed.

        :param item_name: The name of the item to remove.
        :param quantity: The quantity of the item to remove.
        """
        if item_name in self.items:
            if self.items[item_name] > quantity:
                self.items[item_name] -= quantity
            else:
                del self.items[item_name]

    def get_item_quantity(self, item_name):
        """
        Returns the current quantity of the specified item in the inventory.

        :param item_name: The name of the item.
        :return: The current quantity of the item.
        """
        return self.items.get(item_name, 0)

    def list_inventory(self):
        """
        Returns a list of tuples representing the current state of the inventory.
        Each tuple contains an item name and its quantity.

        :return: A list of tuples (item_name, quantity).
        """
        return list(self.items.items())

def calculate_statistics(numbers):
    """
    Computes the mean, median, and mode of a list of numbers.

    Parameters:
    numbers (list): A list of integers or floating-point numbers.

    Returns:
    dict: A dictionary with keys 'mean', 'median', and 'mode'.
    """
    if not numbers:
        raise ValueError("The list should not be empty.")

    # Calculate Mean
    mean = sum(numbers) / len(numbers)

    # Calculate Median
    sorted_numbers = sorted(numbers)
    n = len(sorted_numbers)
    mid = n // 2

    if n % 2 == 0:
        median = (sorted_numbers[mid - 1] + sorted_numbers[mid]) / 2
    else:
        median = sorted_numbers[mid]

    # Calculate Mode
    frequency = {}
    for number in numbers:
        if number in frequency:
            frequency[number] += 1
        else:
            frequency[number] = 1

    max_count = max(frequency.values())
    mode = min([num for num, freq in frequency.items() if freq == max_count])

    return {'mean': mean, 'median': median, 'mode': mode}

def deep_copy_custom(obj):
    """
    Creates a deep copy of the given object.

    Args:
    obj (int, list, tuple, dict): The object to be deep copied.

    Returns:
    int, list, tuple, dict: A deep copy of the input object.

    Raises:
    TypeError: If the object type is not supported for deep copying.
    """
    if isinstance(obj, int):
        return obj
    elif isinstance(obj, list):
        return [deep_copy_custom(item) for item in obj]
    elif isinstance(obj, tuple):
        return tuple(deep_copy_custom(item) for item in obj)
    elif isinstance(obj, dict):
        return {key: deep_copy_custom(value) for key, value in obj.items()}
    else:
        raise TypeError("Unsupported type for deep copying")

