def findPeakCells(m: int, n: int, grid: List[List[int]]) -> List[Tuple[int, int]]:
    def is_peak(i, j):
        # Check top
        if i > 0 and grid[i][j] <= grid[i-1][j]:
            return False
        # Check bottom
        if i < m-1 and grid[i][j] <= grid[i+1][j]:
            return False
        # Check left
        if j > 0 and grid[i][j] <= grid[i][j-1]:
            return False
        # Check right
        if j < n-1 and grid[i][j] <= grid[i][j+1]:
            return False
        return True

    peak_cells = []
    for i in range(m):
        for j in range(n):
            if is_peak(i, j):
                peak_cells.append((i, j))

    peak_cells.sort()  # Ensure lexicographical order
    return peak_cells

def merge_sorted_lists(list1, list2):
    """
    Merges two sorted lists into a single sorted list with unique elements.

    Parameters:
    list1 (List[int]): The first sorted list of integers.
    list2 (List[int]): The second sorted list of integers.

    Returns:
    List[int]: A new list containing all unique elements from both lists in sorted order.
    """
    merged_list = []
    i, j = 0, 0

    while i < len(list1) and j < len(list2):
        if list1[i] < list2[j]:
            if not merged_list or merged_list[-1] != list1[i]:
                merged_list.append(list1[i])
            i += 1
        elif list1[i] > list2[j]:
            if not merged_list or merged_list[-1] != list2[j]:
                merged_list.append(list2[j])
            j += 1
        else:
            if not merged_list or merged_list[-1] != list1[i]:
                merged_list.append(list1[i])
            i += 1
            j += 1

    while i < len(list1):
        if not merged_list or merged_list[-1] != list1[i]:
            merged_list.append(list1[i])
        i += 1

    while j < len(list2):
        if not merged_list or merged_list[-1] != list2[j]:
            merged_list.append(list2[j])
        j += 1

    return merged_list

class PalindromePartition:
    def __init__(self, s: str):
        self.s = s
        self.n = len(s)
        self.dp_cuts = [0] * self.n
        self.dp_palindrome = [[False] * self.n for _ in range(self.n)]

    def initialize_palindrome_table(self) -> None:
        # Every single character is a palindrome
        for i in range(self.n):
            self.dp_palindrome[i][i] = True

        # Check for two characters palindromes
        for i in range(self.n - 1):
            if self.s[i] == self.s[i + 1]:
                self.dp_palindrome[i][i + 1] = True

        # Check for palindromes longer than two characters
        for length in range(3, self.n + 1):
            for i in range(self.n - length + 1):
                j = i + length - 1
                if self.s[i] == self.s[j] and self.dp_palindrome[i + 1][j - 1]:
                    self.dp_palindrome[i][j] = True

    def min_cut(self) -> int:
        self.initialize_palindrome_table()

        for i in range(self.n):
            if self.dp_palindrome[0][i]:
                self.dp_cuts[i] = 0
            else:
                self.dp_cuts[i] = min(self.dp_cuts[j] + 1 for j in range(i) if self.dp_palindrome[j + 1][i])

        return self.dp_cuts[self.n - 1]

class DataTransformer:
    @staticmethod
    def dicts_to_tuples(data: list[dict], keys: list[str]) -> list[tuple]:
        result = []
        for item in data:
            try:
                result.append(tuple(item[key] for key in keys))
            except KeyError as e:
                raise KeyError(f"Missing key in data: {e}")
        return result

    @staticmethod
    def tuples_to_dicts(tuples: list[tuple], keys: list[str]) -> list[dict]:
        if not all(len(t) == len(keys) for t in tuples):
