def number_of_boomerangs(points):
    from collections import defaultdict

    def get_squared_distance(p1, p2):
        return (p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2

    count = 0
    for i in range(len(points)):
        distance_map = defaultdict(int)
        for j in range(len(points)):
            if i != j:
                distance = get_squared_distance(points[i], points[j])
                distance_map[distance] += 1
        for k in distance_map.values():
            count += k * (k - 1)  # Permutations of k items taken 2 at a time: kP2 = k * (k - 1)

    return count

def is_feasible_travel_plan(graph, source):
    """
    Determines if there is a negative-weight cycle reachable from the source in the given graph.

    Parameters:
    graph (dict): The graph represented as an adjacency list with edge weights.
    source (str): The starting location (vertex) in the graph.

    Returns:
    bool: True if there is no reachable negative-weight cycle from the source, otherwise False.
    """
    # Initialize distances from the source
    distance = {vertex: float('inf') for vertex in graph}
    distance[source] = 0

    # Get all the edges in the graph
    edges = []
    for u in graph:
        for v in graph[u]:
            edges.append((u, v, graph[u][v]))

    # Relax edges up to V-1 times, where V is the number of vertices
    V = len(graph)
    for _ in range(V - 1):
        for u, v, w in edges:
            if distance[u] != float('inf') and distance[u] + w < distance[v]:
                distance[v] = distance[u] + w

    # Check for negative-weight cycles by trying to relax one more time
    for u, v, w in edges:
        if distance[u] != float('inf') and distance[u] + w < distance[v]:
            return False

    return True

def smallest_substring_with_two_as_and_two_bs(s):
    """
    Given a string s consisting of only the characters 'a' and 'b', 
    return the length of the smallest substring that contains at least two 'a's and two 'b's. 
    If no such substring exists, return -1.
    """
    n = len(s)
    min_length = float('inf')  # Initialize with a very large value

    for i in range(n):
        count_a = 0
        count_b = 0
        for j in range(i, n):
            if s[j] == 'a':
                count_a += 1
            elif s[j] == 'b':
                count_b += 1

            if count_a >= 2 and count_b >= 2:
                min_length = min(min_length, j - i + 1)
                break

    return min_length if min_length != float('inf') else -1

