    """
    n = len(arr)

    # DP table initialization
    dp = [[False] * (target + 1) for _ in range(n + 1)]

    # Base case: there's always a subset with sum 0 (empty subset)
    for i in range(n + 1):
        dp[i][0] = True

    # DP table computation
