class Matrix:
    def __init__(self, data):
        """
        Initializes the matrix with a given 2D list `data`.
        """
        self.data = data
        self.rows = len(data)
        self.cols = len(data[0]) if self.rows > 0 else 0

    def __str__(self):
        """
        Returns a string representation of the matrix.
        """
        return '\n'.join([' '.join(map(str, row)) for row in self.data])

    def __add__(self, other):
        """
        Implements matrix addition.
        Raises a ValueError if the matrices are not of the same size.
        """
        if self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must be of the same size to add")
        result = [
            [self.data[i][j] + other.data[i][j] for j in range(self.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def __mul__(self, other):
        """
        Implements matrix multiplication.
        Raises a ValueError if the number of columns in the first matrix is not equal to the number of rows in the second matrix.
        """
        if self.cols != other.rows:
            raise ValueError("Number of columns in the first matrix must be equal to number of rows in the second")
        result = [
            [sum(self.data[i][k] * other.data[k][j] for k in range(self.cols)) for j in range(other.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def transpose(self):
        """
        Returns the transpose of the matrix.
        """
        result = [
            [self.data[i][j] for i in range(self.rows)]
            for j in range(self.cols)
        ]
        return Matrix(result)

