def wordBreak(s: str, wordDict: List[str]) -> List[str]:
    word_set = set(wordDict)
    memo = {}

    def backtrack(start):
        if start in memo:
            return memo[start]
        if start == len(s):
            return ['']

        sentences = []
        for end in range(start + 1, len(s) + 1):
            word = s[start:end]
            if word in word_set:
                rest_sentences = backtrack(end)
                for sentence in rest_sentences:
                    full_sentence = word + ("" if sentence == "" else " ") + sentence
                    sentences.append(full_sentence)

        memo[start] = sentences
        return sentences

    return backtrack(0)

def count_unique_pairs(nums, target):
    """
    Returns the number of unique pairs (a, b) in the array such that a + b == target.
    """
    nums_sorted = sorted(nums)
    seen = set()
    unique_pairs = set()

    for num in nums_sorted:
        complement = target - num
        if complement in seen:
            unique_pairs.add((min(num, complement), max(num, complement)))
        seen.add(num)

    return len(unique_pairs)

class GridIslands:
    def __init__(self, m: int, n: int) -> None:
        self.m = m
        self.n = n
        self.grid = [[0] * n for _ in range(m)]
        self.parent = {}
        self.rank = {}
        self.count = 0

    def find(self, position):
        if self.parent[position] != position:
            self.parent[position] = self.find(self.parent[position])
        return self.parent[position]

    def union(self, p1, p2):
        root1 = self.find(p1)
        root2 = self.find(p2)

        if root1 != root2:
            if self.rank[root1] > self.rank[root2]:
                self.parent[root2] = root1
            elif self.rank[root1] < self.rank[root2]:
                self.parent[root1] = root2
            else:
                self.parent[root2] = root1
                self.rank[root1] += 1
            self.count -= 1

    def addLand(self, x: int, y: int) -> int:
        if self.grid[x][y] == 1:
            return self.count

        self.grid[x][y] = 1
        position = (x, y)
        self.parent[position] = position
        self.rank[position] = 0
        self.count += 1

        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < self.m and 0 <= ny < self.n and self.grid[nx][ny] == 1:
                self.union(position, (nx, ny))

        return self.count

