def max_subarray_with_atleast_k(array: List[int], k: int) -> int:
    def kadane(array):
        max_current = max_global = array[0]
        for num in array[1:]:
            max_current = max(num, max_current + num)
            if max_current > max_global:
                max_global = max_current
        return max_global

    n = len(array)

    if n == 0:
        return 0

    max_sum = float('-inf')
    current_sum = sum(array[:k])
    kadane_residue = [0] * n
    kadane_residue[k-1] = current_sum

    for end in range(k, n):
        current_sum = current_sum + array[end] - array[end - k]
        kadane_residue[end] = max(kadane_residue[end - 1] + array[end], current_sum)
        max_sum = max(max_sum, kadane_residue[end])

    max_k_sum = kasum = sum(array[:k])
    for i in range(k, n):
        kasum += array[i] - array[i-k]
        max_k_sum = max(max_k_sum, kasum)

    return max(max_sum, max_k_sum)

def min_jumps(arr):
    """
    Returns the minimum number of jumps required to reach the end of the list,
    or -1 if it is not possible.
    """
    if len(arr) <= 1:
        return 0

    if arr[0] == 0:
        return -1

    max_reach = arr[0]
    steps = arr[0]
    jumps = 1

    for i in range(1, len(arr)):
        if i == len(arr) - 1:
            return jumps

        max_reach = max(max_reach, i + arr[i])

        steps -= 1

        if steps == 0:
            jumps += 1

            if i >= max_reach:
                return -1

            steps = max_reach - i

    return -1

