def maximum_sum(nums):
    n = len(nums)

    if n == 1:
        return nums[0]

    max_end_here = [0] * n
    max_start_here = [0] * n

    max_end_here[0] = nums[0]
    for i in range(1, n):
        max_end_here[i] = max(nums[i], max_end_here[i - 1] + nums[i])

    max_start_here[-1] = nums[-1]
    for i in range(n - 2, -1, -1):
        max_start_here[i] = max(nums[i], max_start_here[i + 1] + nums[i])

    max_sum = max(max_end_here)
    for i in range(1, n - 1):
        max_sum = max(max_sum, max_end_here[i - 1] + max_start_here[i + 1])  

    return max_sum

def can_partition_to_max_weight(weights, maxWeight):
    totalWeight = sum(weights)
    if totalWeight > 2 * maxWeight:
        return False

    n = len(weights)
    target = maxWeight
    dp = [False] * (target + 1)
    dp[0] = True

    for weight in weights:
        for j in range(target, weight - 1, -1):
            if dp[j - weight]:
                dp[j] = True

    for w in range(target, -1, -1):
        if dp[w] and totalWeight - w <= maxWeight:
            return True

    return False

