import re

def normalize_dates(dates):
    month_dict = {
        "January": "01", "Jan": "01", "February": "02", "Feb": "02",
        "March": "03", "Mar": "03", "April": "04", "Apr": "04",
        "May": "05", "June": "06", "Jun": "06", "July": "07", "Jul": "07",
        "August": "08", "Aug": "08", "September": "09", "Sep": "09",
        "October": "10", "Oct": "10", "November": "11", "Nov": "11",
        "December": "12", "Dec": "12"
    }

    normalized_dates = []

    for date in dates:
        if match := re.match(r'(\w+)\s+(\d{1,2}),\s+(\d{4})', date):
            month, day, year = match.groups()
            month = month_dict[month]
            normalized_date = f"{year}-{month}-{int(day):02}"

        elif match := re.match(r'(\d{2})/(\d{2})/(\d{4})', date):
            month, day, year = match.groups()
            normalized_date = f"{year}-{month}-{day}"

        elif match := re.match(r'(\d{4})-(\d{2})-(\d{2})', date):
            normalized_date = date  # Already in correct format

        elif match := re.match(r'(\d{1,2})[a-z]{2}\s+(\w+),\s+(\d{4})', date):
            day, month, year = match.groups()
            month = month_dict[month]
            normalized_date = f"{year}-{month}-{int(day):02}"

        elif match := re.match(r'(\d{2})\.(\d{2})\.(\d{4})', date):
            month, day, year = match.groups()
            normalized_date = f"{year}-{month}-{day}"

        elif match := re.match(r'(\d{4})\.(\d{2})\.(\d{2})', date):
            year, month, day = match.groups()
            normalized_date = f"{year}-{month}-{day}"

        else:
            raise ValueError(f"Unrecognized date format: {date}")

        normalized_dates.append(normalized_date)

    return normalized_dates

def split_array(nums, p):
    def can_split(mid):
        current_sum = 0
        count = 1
        for num in nums:
            current_sum += num
            if current_sum > mid:
                current_sum = num
                count += 1
                if count > p:
                    return False
        return True

    left, right = max(nums), sum(nums)
    while left < right:
        mid = (left + right) // 2
        if can_split(mid):
            right = mid
        else:
            left = mid + 1
    return left

def check_inclusion(s1: str, s2: str) -> bool:
    from collections import Counter

    len1, len2 = len(s1), len(s2)
    if len1 > len2:
        return False

    s1_count = Counter(s1)
    s2_count = Counter(s2[:len1])

    if s1_count == s2_count:
        return True

    for i in range(len1, len2):
        s2_count[s2[i]] += 1
        s2_count[s2[i - len1]] -= 1

        if s2_count[s2[i - len1]] == 0:
            del s2_count[s2[i - len1]]

        if s1_count == s2_count:
            return True

    return False

def knapsack(T, data):
    results = []

    for t in range(T):
        N, C = data[t]['N'], data[t]['C']
        weights = data[t]['weights']
        values = data[t]['values']

        dp = [[0 for x in range(C + 1)] for x in range(N + 1)]

        for i in range(N + 1):
            for w in range(C + 1):
                if i == 0 or w == 0:
                    dp[i][w] = 0
                elif weights[i-1] <= w:
                    dp[i][w] = max(values[i-1] + dp[i-1][w - weights[i-1]], dp[i-1][w])
                else:
                    dp[i][w] = dp[i-1][w]

        results.append(dp[N][C])

    return results

