def find_lca(n, managers, a, b):
    from collections import defaultdict, deque

    # Create the parent dictionary to hold the manager for each employee
    parent = {1: None}
    for i, manager in enumerate(managers, start=2):
        parent[i] = manager

    # Function to find the ancestors of an employee
    def find_ancestors(employee):
        ancestors = set()
        while employee is not None:
            ancestors.add(employee)
            employee = parent[employee]
        return ancestors

    # Find ancestors of both employees a and b
    ancestors_a = find_ancestors(a)
    ancestors_b = find_ancestors(b)

    # Find the lowest common ancestor by traversing from employee a upwards
    while b not in ancestors_a:
        b = parent[b]

    return b

