class BinaryTreeNode:
    def __init__(self, value):
        """
        Initialize a new binary tree node with the given value.

        :param value: The value to be stored in the node.
        """
        self.value = value
        self.left = None
        self.right = None

    def insert(self, value):
        """
        Insert a new value into the binary tree, maintaining the binary search tree property.

        :param value: The value to be inserted.
        """
        if value <= self.value:
            if self.left is None:
                self.left = BinaryTreeNode(value)
            else:
                self.left.insert(value)
        else:
            if self.right is None:
                self.right = BinaryTreeNode(value)
            else:
                self.right.insert(value)

    def in_order_traversal(self):
        """
        Perform an in-order traversal of the binary tree and return the values in a list.

        :return: A list of values in in-order traversal order.
        """
        traversal = []
        if self.left:
            traversal += self.left.in_order_traversal()
        traversal.append(self.value)
        if self.right:
            traversal += self.right.in_order_traversal()
        return traversal

def count_paths(n, m, blocked_cells):
    if (n, m) == (1, 1):
        return 0 if (1, 1) in blocked_cells else 1

    blocked_set = set(blocked_cells)

    if (1, 1) in blocked_set or (n, m) in blocked_set:
        return 0

    dp = [[0] * m for _ in range(n)]
    dp[0][0] = 1

    # Fill the dp array
    for i in range(n):
        for j in range(m):
            if (i + 1, j + 1) in blocked_set:
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i - 1][j]
                if j > 0:
                    dp[i][j] += dp[i][j - 1]

    return dp[n - 1][m - 1]

def party_distribution(t, k):
    """
    Returns the amount of candies each child can get and the number of bags needed.
    If the candies cannot be distributed evenly, returns 0 for both values.
    """
    if t < k:
        return {"Candies_per_child": 0, "Bags_needed": 0}

    max_candies_per_child = t // k
    max_candies_per_child -= max_candies_per_child % 100

    if max_candies_per_child == 0:
        return {"Candies_per_child": 0, "Bags_needed": 0}

    total_candies_distributed = max_candies_per_child * k
    bags_needed = (total_candies_distributed + 99) // 100  # ceiling division

    return {"Candies_per_child": max_candies_per_child, "Bags_needed": bags_needed}

