    If multiple peaks exist, returns the highest one. Returns None if no peak exists.

    :param prices: List of integers representing stock prices.
    :return: The highest peak or None if no peak exists.
    """
    if len(prices) < 3:
        return None

    highest_peak = None

    for i in range(1, len(prices) - 1):
        if prices[i] > prices[i - 1] and prices[i] > prices[i + 1]:
            if highest_peak is None or prices[i] > highest_peak:
                highest_peak = prices[i]

    return highest_peak

