def highlight_symbols(words, symbols):
    class TreeNode:
        def __init__(self):
            self.children = {}
            self.symbol = None

    # Building the Trie/Tree from the symbols
    root = TreeNode()
    for symbol in symbols:
        node = root
        for char in symbol:
            if char not in node.children:
                node.children[char] = TreeNode()
            node = node.children[char]
        node.symbol = symbol

    def find_longest_match(word):
        node = root
        longest_match = None
        match_len = 0

        for i in range(len(word)):
            curr = node
            j = i
            while j < len(word) and word[j] in curr.children:
                curr = curr.children[word[j]]
                if curr.symbol:
                    if (j - i + 1) > match_len:
                        longest_match = (i, j + 1, curr.symbol)
                        match_len = j - i + 1
                j += 1

        return longest_match

    result = []
    for word in words:
        match = find_longest_match(word)
        if match:
            start, end, symbol = match
            result.append(f"{word[:start]}[{symbol}]{word[end:]}")
