class HashFunction:
    def __init__(self, size):
        """Initializes the hash table with a given size."""
        self.size = size
        self.table = [[] for _ in range(size)]

    def hash(self, key):
        """Computes the hash value of a given key using a simple hash function."""
        return hash(key) % self.size

    def insert(self, key, value):
        """Inserts a key-value pair into the hash table. Updates the value if the key already exists."""
        index = self.hash(key)
        for i, (k, v) in enumerate(self.table[index]):
            if k == key:
                self.table[index][i] = (key, value)
                return
        self.table[index].append((key, value))

    def search(self, key):
        """Searches for a key in the hash table and returns the corresponding value if found. Returns None if the key does not exist."""
        index = self.hash(key)
        for k, v in self.table[index]:
            if k == key:
                return v
        return None

    def delete(self, key):
        """Deletes a key-value pair from the hash table if the key exists. Does nothing if the key does not exist."""
        index = self.hash(key)
        for i, (k, v) in enumerate(self.table[index]):
            if k == key:
                del self.table[index][i]
                return

    def display(self):
        """Displays the current state of the hash table in a readable format."""
        print("Hash Table:")
        for i in range(self.size):
            print(f"Index {i}:", self.table[i])

def compress(data: str) -> str:
    """
    Compress the input string using Run-Length Encoding (RLE).
    """
    if not data:
        return ""

    compressed = []
    count = 1
    current_char = data[0]

    for i in range(1, len(data)):
        if data[i] == current_char:
            count += 1
            if count == 9:  # reset every 9 to maintain single char representation
                compressed.append(f"{current_char}{count}")
                count = 0
        else:
            if count > 0:
                compressed.append(f"{current_char}{count}")
            current_char = data[i]
            count = 1

    if count > 0:
        compressed.append(f"{current_char}{count}")

    return ''.join(compressed)

def decompress(encoded_data: str) -> str:
    """
    Decompress the RLE encoded string back to its original form.
    """
    if not encoded_data:
        return ""

    decompressed = []
    i = 0
    while i < len(encoded_data):
        char = encoded_data[i]
        count = int(encoded_data[i + 1])
        decompressed.append(char * count)
        i += 2

    return ''.join(decompressed)

class WordDictionary:
    def __init__(self):
        self.trie = {}

    def add_word(self, word: str) -> None:
        node = self.trie
        for char in word:
            if char not in node:
                node[char] = {}
            node = node[char]
        node['#'] = True  # Mark the end of a word

    def search(self, word: str) -> bool:
        return self._search_in_node(word, 0, self.trie)

    def _search_in_node(self, word, index, node):
        if index == len(word):
            return '#' in node
        char = word[index]
        if char == '.':
            for child in node:
                if child != '#' and self._search_in_node(word, index + 1, node[child]):
                    return True
        elif char in node:
            return self._search_in_node(word, index + 1, node[char])
        return False

