def get_feedback(guess: str, secret: str) -> (int, int):
    correct_positions = sum(g == s for g, s in zip(guess, secret))
    wrong_positions = sum(min(guess.count(c), secret.count(c)) for c in set(guess)) - correct_positions
    return correct_positions, wrong_positions

