def shortest_sequence_to_return_to_origin(n, commands):
    """
    Returns the shortest sequence of commands to bring the robotic arm back to position 0
    :param n: int - number of commands
    :param commands: string - sequence of commands consisting of 'L' and 'R'
    :return: string - the shortest sequence of commands to return to origin or an empty line if already at position 0
    """
    # Calculate the net position
    net_position = 0
    for command in commands:
        if command == 'L':
            net_position -= 1
        elif command == 'R':
            net_position += 1

    # If already at the origin
    if net_position == 0:
        return ""

    # To move back to the origin
    if net_position > 0:
        return 'L' * net_position
    else:
        return 'R' * abs(net_position)

