def reverse_pairs(nums):
    """
    Returns the number of reverse pairs in the array such that i < j and nums[i] > 2 * nums[j].
    """
    def merge_sort(nums, l, r):
        if l >= r:
            return 0
        mid = (l + r) // 2
        count = merge_sort(nums, l, mid) + merge_sort(nums, mid + 1, r)
        j = mid + 1
        for i in range(l, mid + 1):
            while j <= r and nums[i] > 2 * nums[j]:
                j += 1
            count += j - (mid + 1)

        # Merging the two halves
        left_part = nums[l:mid+1]
        right_part = nums[mid+1:r+1]
        i = 0
        j = 0
        for k in range(l, r+1):
            if i < len(left_part) and (j >= len(right_part) or left_part[i] <= right_part[j]):
                nums[k] = left_part[i]
                i += 1
            else:
                nums[k] = right_part[j]
                j += 1

        return count

    return merge_sort(nums, 0, len(nums) - 1)

