def get_users_still_inside(logs):
    """
    Identify users who were still inside the event after the last log entry.
    A user is inside the event if they have more 'enter' logs than 'exit' logs.

    :param logs: list of log entries
    :return: sorted list of user names who were still inside
    """
    event_logs = {}

    for log in logs:
        action, user = log.split(':')
        user = user.strip().lower()

        if user not in event_logs:
            event_logs[user] = 0

        if action.strip().lower() == "enter":
            event_logs[user] += 1
        elif action.strip().lower() == "exit":
            event_logs[user] -= 1

    users_inside = [user for user, count in event_logs.items() if count > 0]

    return sorted(users_inside)

def find_and_replace_pattern(words, pattern):
    """
    Returns a list of words that match the given pattern using bijection.
    """
    def match(word):
        if len(word) != len(pattern):
            return False
        p_to_w, w_to_p = {}, {}
        for p, w in zip(pattern, word):
            if p in p_to_w and p_to_w[p] != w:
                return False
            if w in w_to_p and w_to_p[w] != p:
                return False
            p_to_w[p] = w
            w_to_p[w] = p
        return True

    return [word for word in words if match(word)]

