def find_minimized_max_edge(n, coordinates):
    import heapq

    # Helper function to calculate Manhattan distance
    def manhattan_dist(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    # Create all edges with their Manhattan distances
    edges = []
    for i in range(n):
        for j in range(i + 1, n):
            distance = manhattan_dist(coordinates[i], coordinates[j])
            edges.append((distance, i, j))

    # Kruskal's algorithm to find MST
    edges.sort()
    parent = list(range(n))

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rootX = find(x)
        rootY = find(y)
        if rootX != rootY:
            parent[rootY] = rootX

    mst_max_edge = 0
    for distance, u, v in edges:
        if find(u) != find(v):
            union(u, v)
            mst_max_edge = distance
            # If MST is connected with all n nodes
            if len(set(find(x) for x in range(n))) == 1:
                break

    return mst_max_edge

