def num_ways_to_deliver(n, m, grid):
    if grid[0][0] == 'R' or grid[n-1][m-1] == 'R':
        return 0

    dp = [[0] * m for _ in range(n)]
    dp[0][0] = 1

    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'R':
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                    dp[i][j] %= MOD
                if j > 0:
                    dp[i][j] += dp[i][j-1]
                    dp[i][j] %= MOD

    return dp[n-1][m-1]

