def shortest_palindrome(s: str) -> str:
    """
    Finds the shortest palindrome by appending characters at the end of the given string.
    """
    def is_palindrome(check_str):
        return check_str == check_str[::-1]

    if is_palindrome(s):
        return s

    for i in range(len(s)):
        if is_palindrome(s[i:]):
            append_str = s[:i][::-1]
            return s + append_str

    return s[::-1] + s  # In worst case, append the reversed string except for the first char

