class UnionFind:
    def __init__(self, size):
        self.parent = list(range(size))
        self.rank = [0] * size
        self.count = 0

    def find(self, u):
        if self.parent[u] != u:
            self.parent[u] = self.find(self.parent[u])
        return self.parent[u]

    def union(self, u, v):
        root_u = self.find(u)
        root_v = self.find(v)
        if root_u != root_v:
            if self.rank[root_u] > self.rank[root_v]:
                self.parent[root_v] = root_u
            elif self.rank[root_u] < self.rank[root_v]:
                self.parent[root_u] = root_v
            else:
                self.parent[root_v] = root_u
                self.rank[root_u] += 1
            self.count -= 1
            return True
        return False

    def increment_count(self):
        self.count += 1

    def get_count(self):
        return self.count


def num_islands2(m, n, positions):
    def get_index(x, y):
        return x * n + y

    uf = UnionFind(m * n)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    occupied = set()
    result = []

    for x, y in positions:
        if (x, y) in occupied:
            result.append(uf.get_count())
            continue

        index = get_index(x, y)
        uf.increment_count()
        occupied.add((x, y))

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n and (nx, ny) in occupied:
                uf.union(index, get_index(nx, ny))

        result.append(uf.get_count())

    return result

