def longest_subsequence_with_difference(arr, difference):
    """
    Returns the length of the longest subsequence in the array that forms an arithmetic sequence
    with the given difference.
    """
    dp = {}
    max_length = 0

    for num in arr:
        if num - difference in dp:
            dp[num] = dp[num - difference] + 1
