def minimal_moves_to_partition(n, scores):
    """
    Find the minimal number of moves required to partition the array into two equal parts:
    one part containing multiples of 3 and the other part containing non-multiples of 3.
    """
    multiple_of_3 = sum(1 for score in scores if score % 3 == 0)
    non_multiple_of_3 = n // 2 - multiple_of_3

    if abs(non_multiple_of_3) <= n // 2:
        return abs(non_multiple_of_3)
    else:
        return n // 2

class MinStack:
    def __init__(self):
        # Initialize the main stack and an auxiliary stack to keep track of minimum elements
        self.stack = []
        self.min_stack = []

    def push(self, x: int) -> None:
        """
        Push element x onto the stack.
        """
        self.stack.append(x)
        if not self.min_stack or x <= self.min_stack[-1]:
            self.min_stack.append(x)

    def pop(self) -> None:
        """
        Removes the element on top of the stack.
        """
        if self.stack:
            x = self.stack.pop()
            if x == self.min_stack[-1]:
                self.min_stack.pop()

    def top(self) -> int:
        """
        Get the top element of the stack.
        """
        if self.stack:
            return self.stack[-1]

    def get_min(self) -> int:
        """
        Retrieve the minimum element in the stack.
        """
        if self.min_stack:
            return self.min_stack[-1]

    def is_empty(self) -> bool:
        """
        Check if the stack is empty.
        """
        return len(self.stack) == 0

