def shortest_length(s):
    """
    Compute the length of the shortest possible string after repeatedly removing substrings "ab" or "ba".

    Parameters:
    s (str): Input string consisting of lowercase English letters.

    Returns:
    int: Length of the shortest possible string.
    """
    stack = []
    for char in s:
        if stack and ((stack[-1] == 'a' and char == 'b') or (stack[-1] == 'b' and char == 'a')):
            stack.pop()
        else:
            stack.append(char)
    return len(stack)

