def three_sum(arr, target):
    """
    Finds all unique triplets in the array which gives the sum of target.

    :param arr: List[int] - The input array of integers
    :param target: int - The target sum for the triplets
    :return: List[List[int]] - List of unique triplets that sum up to the target
    """
    arr.sort()
    result = []
    n = len(arr)

    for i in range(n - 2):
        if i > 0 and arr[i] == arr[i - 1]:
            continue  # Skip duplicate elements

        left, right = i + 1, n - 1
        while left < right:
            current_sum = arr[i] + arr[left] + arr[right]

            if current_sum == target:
                result.append([arr[i], arr[left], arr[right]])

                while left < right and arr[left] == arr[left + 1]:
                    left += 1  # Skip duplicates
                while left < right and arr[right] == arr[right - 1]:
                    right -= 1  # Skip duplicates

                left += 1
                right -= 1

            elif current_sum < target:
                left += 1
            else:
                right -= 1

    return result

def longest_zigzag_sequence(nums):
    """
    Returns the length of the longest zigzag sequence in the given list of integers.
    """
    n = len(nums)
    if n < 2:
        return n

    up = [1] * n
    down = [1] * n

    for i in range(1, n):
        if nums[i] > nums[i-1]:
            up[i] = down[i-1] + 1
            down[i] = down[i-1]
        elif nums[i] < nums[i-1]:
            down[i] = up[i-1] + 1
            up[i] = up[i-1]
        else:
            up[i] = up[i-1]
            down[i] = down[i-1]

    return max(up[-1], down[-1])

