def find_max_prime(n):
    """
    Returns the largest prime number less than or equal to n.
    If no prime number exists, returns None.

    :param n: An integer (1 ≤ n ≤ 10^6)
    :return: The largest prime number ≤ n or None
    """
    def is_prime(num):
        """
        Checks if a number is prime.

        :param num: An integer
        :return: True if num is prime, False otherwise
        """
        if num <= 1:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num**0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    for num in range(n, 1, -1):
        if is_prime(num):
            return num
    return None

