def floyd_warshall(n, graph, threshold):
    # Initialize distance matrix with infinity
    dist = [[float('inf')] * n for _ in range(n)]

    # Distance from a node to itself is 0
    for i in range(n):
        dist[i][i] = 0

    # Fill in the graph edges
    for u, v, w in graph:
        dist[u][v] = dist[v][u] = w

    # Floyd-Warshall to compute the shortest paths
    for k in range(n):
        for i in range(n):
            for j in range(n):
                if dist[i][j] > dist[i][k] + dist[k][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    return dist

def can_find_k_cities_with_threshold(n, graph, k, threshold):
    dist = floyd_warshall(n, graph, threshold)

    # Check every combination of `k` nodes
    from itertools import combinations
    for combination in combinations(range(n), k):
        if all(dist[u][v] <= threshold for u, v in combinations(combination, 2)):
            return True
    return False

