def min_fib_steps(X):
    """
    Returns the minimum number of Fibonacci steps required to reach exactly X years.
    """
    if X == 1:
        return 1

    # Generate Fibonacci numbers up to X
    fibs = [1, 1]
    while fibs[-1] < X:
        fibs.append(fibs[-1] + fibs[-2])

    # Use a greedy approach to find the minimum number of steps
    steps = 0
    remaining = X
    for fib in reversed(fibs):
        if remaining >= fib:
            remaining -= fib
            steps += 1
        if remaining == 0:
            break

    return steps

