def largest_subarray_with_sum_k(arr, k):
    """
    Determines the size of the largest contiguous subarray with sum equal to k.

    :param arr: List of integers
    :param k: Integer target sum
    :return: Integer size of the largest subarray with sum equal to k
    """
    sum_to_index = {}
    current_sum = 0
    max_length = 0

    for i in range(len(arr)):
        current_sum += arr[i]

        if current_sum == k:
            max_length = i + 1

        if current_sum - k in sum_to_index:
            max_length = max(max_length, i - sum_to_index[current_sum - k])

        if current_sum not in sum_to_index:
            sum_to_index[current_sum] = i

    return max_length

