def find_path(maze: List[List[int]]) -> int:
    n, m = len(maze), len(maze[0])
    if maze[0][0] == 0 or maze[n-1][m-1] == 0:
        return -1

    directions = [(1, 0), (0, 1), (-1, 0), (0, -1)]
    queue = deque([(0, 0, 1)])
    visited = [[False] * m for _ in range(n)]
    visited[0][0] = True

    while queue:
        x, y, dist = queue.popleft()

        if x == n-1 and y == m-1:
            return dist - 1  # Exclude the start point

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m and not visited[nx][ny] and maze[nx][ny] == 1:
                visited[nx][ny] = True
                queue.append((nx, ny, dist + 1))

    return -1

def min_bonus(ratings):
    n = len(ratings)
    if n == 0: 
        return 0

    bonus = [1] * n

    # First pass from left to right
    for i in range(1, n):
        if ratings[i] > ratings[i - 1]:
            bonus[i] = bonus[i - 1] + 1

    # Second pass from right to left
    for i in range(n - 2, -1, -1):
        if ratings[i] > ratings[i + 1]:
            bonus[i] = max(bonus[i], bonus[i + 1] + 1)

    return sum(bonus)

