class LinkedList:
    def __init__(self):
        """Initializes an empty linked list."""
        self.head = None

    def append(self, value):
        """Adds a new node with the specified value to the end of the list."""
        new_node = Node(value)
        if not self.head:
            self.head = new_node
            return
        last_node = self.head
        while last_node.next:
            last_node = last_node.next
        last_node.next = new_node

    def remove(self, value):
        """Removes the first node with the specified value from the list."""
        if not self.head:
            return
        if self.head.value == value:
            self.head = self.head.next
            return
        current_node = self.head
        while current_node.next:
            if current_node.next.value == value:
                current_node.next = current_node.next.next
                return
            current_node = current_node.next

    def contains(self, value):
        """Returns True if the list contains a node with the specified value, otherwise returns False."""
        current_node = self.head
        while current_node:
            if current_node.value == value:
                return True
            current_node = current_node.next
        return False

    def display(self):
        """Prints the values of all nodes in the list in order, separated by spaces."""
        current_node = self.head
        values = []
        while current_node:
            values.append(str(current_node.value))
            current_node = current_node.next
        print(" ".join(values))

