def min_operations_to_uniform(s):
    """
    Returns the minimum number of operations needed to make the entire string consist of only one type of character.
    """
    if not s:
        return 0

    # Count the number of 'a' groups and 'b' groups
    count_a = 0
    count_b = 0

    # Initialize the previous character for comparison
    prev_char = s[0]
    if prev_char == 'a':
        count_a += 1
    else:
        count_b += 1

    # Iterate through the string to count groups
    for char in s[1:]:
        if char != prev_char:
            if char == 'a':
                count_a += 1
            else:
                count_b += 1
            prev_char = char

    return min(count_a, count_b)

def include_files(files, start):
    """
    Simulates the `include` directive by merging the contents of the included files.

    Args:
        files (dict): A dictionary where the keys are file names and the values are the content of the files.
        start (str): The starting file name to begin the merging process.

    Returns:
        str: The final merged content after including all specified files.
    """
    def process_file(file_name, seen_files):
        if file_name in seen_files:
            raise ValueError("Circular inclusion detected!")
        if file_name not in files:
            raise FileNotFoundError(f"File '{file_name}' not found.")

        seen_files.add(file_name)
        content = []
        for line in files[file_name].splitlines():
            if line.startswith("include "):
                include_file = line.split(" ")[1]
                content.append(process_file(include_file, seen_files))
            else:
                content.append(line)
        seen_files.remove(file_name)
        return "\n".join(content)

    return process_file(start, set())

def knuth_morris_pratt(text, pattern):
    """
    Returns the starting indices of all occurrences of the pattern in the text using the KMP algorithm.
    """
    def compute_lps(pattern):
        """
        Computes the Longest Prefix that is also a Suffix (LPS) array for the given pattern.
        """
        lps = [0] * len(pattern)
        length = 0  # length of the previous longest prefix suffix
        i = 1

        while i < len(pattern):
            if pattern[i] == pattern[length]:
                length += 1
                lps[i] = length
                i += 1
            else:
                if length != 0:
                    length = lps[length - 1]
                else:
                    lps[i] = 0
                    i += 1
        return lps

    # Edge case handling
    if not text or not pattern or len(pattern) > len(text):
        return []

    lps = compute_lps(pattern)
    result = []
    i = 0  # index for text
    j = 0  # index for pattern

    while i < len(text):
        if text[i] == pattern[j]:
            i += 1
            j += 1

        if j == len(pattern):
            result.append(i - j)
            j = lps[j - 1]
        elif i < len(text) and text[i] != pattern[j]:
            if j != 0:
                j = lps[j - 1]
            else:
                i += 1

    return result

