def is_path_exist(grid):
    N = len(grid)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Find the coordinates of 'S' and 'E'
    start = end = None
    for i in range(N):
        for j in range(N):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    if not start or not end:
        return False

    def is_valid(x, y):
        return 0 <= x < N and 0 <= y < N and grid[x][y] in {'.', 'E'}

    # Use BFS to find a path from S to E
    from collections import deque
    queue = deque([start])
    visited = set([start])

    while queue:
        x, y = queue.popleft()
        if (x, y) == end:
            return True
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny) and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny))

    return False

def max_profit(prices):
    """
    Calculate the maximum profit from a single buy and sell transaction.

    :param prices: List[int] - A list of integers representing the stock prices on consecutive days.
    :return: int - The maximum profit that can be achieved. If no profit is possible, returns 0.
    """
    if not prices:
        return 0

    min_price = prices[0]
    max_profit = 0

    for price in prices:
        if price < min_price:
            min_price = price
        elif price - min_price > max_profit:
            max_profit = price - min_price

    return max_profit

