    """
    dp = [[0] * n for _ in range(n)]
    dp[0][0] = grid[0][0]

    for i in range(1, n):
        dp[i][0] = dp[i-1][0] + grid[i][0]
        dp[0][i] = dp[0][i-1] + grid[0][i]

    for i in range(1, n):
        for j in range(1, n):
            dp[i][j] = min(dp[i-1][j], dp[i][j-1]) + grid[i][j]

    return dp[n-1][n-1]

def longest_balanced_segment(n, A):
    # Dictionary to store the first occurrence of each prefix sum
    prefix_sums = {0: -1}
    prefix_sum = 0
    max_length = -1

    for i in range(n):
        prefix_sum += A[i]
        if prefix_sum in prefix_sums:
            max_length = max(max_length, i - prefix_sums[prefix_sum])
        else:
            prefix_sums[prefix_sum] = i

    return max_length

