from typing import List, Tuple
import math

def closest_and_farthest_points(points: List[Tuple[float, float]]) -> Tuple[Tuple[Tuple[float, float], Tuple[float, float]], Tuple[Tuple[float, float], Tuple[float, float]]]:
    min_distance = float('inf')
    max_distance = 0
    closest_pair = (points[0], points[1])
    farthest_pair = (points[0], points[1])

    for i in range(len(points)):
        for j in range(i + 1, len(points)):
            distance = math.dist(points[i], points[j])
            if distance < min_distance:
                min_distance = distance
                closest_pair = (points[i], points[j])
            if distance > max_distance:
                max_distance = distance
                farthest_pair = (points[i], points[j])

    return (closest_pair, farthest_pair)

def find_top_two_students(results):
    """
    Given a list of tuples (student_name, score), return a list containing the names of the students
    with the highest and second highest scores. If no second highest score exists, return only the
    highest scoring student's name.
    """
    if not results:
        return []

    first = second = float('-inf')
    first_student = second_student = None

    for name, score in results:
        if score > first:
            second, second_student = first, first_student
            first, first_student = score, name
        elif first > score > second:
            second, second_student = score, name

    if second_student is not None:
        return [first_student, second_student]
    else:
        return [first_student]

def max_gems_collected(n, grid):
    def preprocess_grid(grid):
        """ Preprocess the grid to create a sum table """
        sum_grid = [[0] * n for _ in range(n)]

        for r in range(n):
            row_sum = 0
            for c in range(n):
                row_sum += 1 if grid[r][c] == 'G' else 0
                sum_grid[r][c] = row_sum + (sum_grid[r-1][c] if r > 0 else 0)

        return sum_grid

    def get_sum(x1, y1, x2, y2, sum_grid):
        """ Get the sum of gems in the rectangular region (x1, y1) to (x2, y2) """
        total = sum_grid[x2][y2]
        if x1 > 0:
            total -= sum_grid[x1-1][y2]
        if y1 > 0:
            total -= sum_grid[x2][y1-1]
        if x1 > 0 and y1 > 0:
            total += sum_grid[x1-1][y1-1]
        return total

    sum_grid = preprocess_grid(grid)
    max_gems = 0

    for x1 in range(n):
        for x2 in range(x1, n):
            for y1 in range(n):
                for y2 in range(y1, n):
                    max_gems = max(max_gems, get_sum(x1, y1, x2, y2, sum_grid))

    return max_gems

def remove_invalid_parentheses(s: str):
    def is_valid(string):
        count = 0
        for char in string:
            if char == '(':
                count += 1
            elif char == ')':
                count -= 1
                if count < 0:
                    return False
        return count == 0

    from collections import deque

    if not s:
        return [""]

    visited = set([s])
    queue = deque([s])
    found = False
    valid_expressions = []

    while queue:
        current_string = queue.popleft()

        if is_valid(current_string):
            found = True
            valid_expressions.append(current_string)

        if found:
            continue

        for i in range(len(current_string)):
            if current_string[i] not in ('(', ')'):
                continue
            next_string = current_string[:i] + current_string[i+1:]
            if next_string not in visited:
                visited.add(next_string)
                queue.append(next_string)

    return valid_expressions

def restore_string(s: str, indices: list) -> str:
    """
    Restores the string s according to the provided indices array
    """
    shuffled = [''] * len(s)
    for i, index in enumerate(indices):
        shuffled[index] = s[i]
    return ''.join(shuffled)

def is_path_exists(n, m, grid):
    def bfs(start, target):
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # four possible directions: up, down, left, right
        queue = [start]
        visited = set()
        visited.add(start)

        while queue:
            x, y = queue.pop(0)
            if (x, y) == target:
                return True

            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < n and 0 <= ny < m and grid[nx][ny] in ('.', 'T') and (nx, ny) not in visited:
                    queue.append((nx, ny))
                    visited.add((nx, ny))

        return False

    start = None
    target = None

    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'T':
                target = (i, j)

    if not start or not target:
        return "NO"

    return "YES" if bfs(start, target) else "NO"

