package main

import "strconv"

func next_smallest_palindrome(num int) int {
	if num < 0 {
		return 0
	}
	s := strconv.Itoa(num)
	n := len(s)
	digits := make([]int, n)
	for i := 0; i < n; i++ {
		digits[i] = int(s[i] - '0')
	}

	// Special case: all digits are 9 (e.g. 9 -> 11, 99 -> 101, 999 -> 1001).
	all9 := true
	for _, d := range digits {
		if d != 9 {
			all9 = false
			break
		}
	}
	if all9 {
		res := 1
		for k := 0; k < n; k++ {
			res *= 10
		}
		return res + 1
	}

	mid := n / 2
	i := mid - 1
	j := mid
	if n%2 == 1 {
		j = mid + 1
	}

	// Find the first mismatching pair moving outward from the middle.
	for i >= 0 && digits[i] == digits[j] {
		i--
		j++
	}
	// If the input is already a palindrome (i < 0) or the mirrored left half
	// would produce a smaller number, we must increment the middle.
	leftSmaller := i < 0 || digits[i] < digits[j]

	// Mirror the left half onto the right half.
	i = mid - 1
	j = mid
	if n%2 == 1 {
		j = mid + 1
	}
	for i >= 0 {
		digits[j] = digits[i]
		i--
		j++
	}

	if leftSmaller {
		carry := 1
		i = mid - 1
		j = mid
		if n%2 == 1 {
			digits[mid] += carry
			carry = digits[mid] / 10
			digits[mid] %= 10
			j = mid + 1
		}
		for i >= 0 {
			digits[i] += carry
			carry = digits[i] / 10
			digits[i] %= 10
			digits[j] = digits[i]
			i--
			j++
		}
	}

	res := 0
	for _, d := range digits {
		res = res*10 + d
	}
	return res
}

