func pancake_sort(nums []int) []int {
	arr := make([]int, len(nums))
	copy(arr, nums)
	flip := func(k int) {
		for i, j := 0, k; i < j; i, j = i+1, j-1 {
			arr[i], arr[j] = arr[j], arr[i]
		}
	}
	for size := len(arr); size > 1; size-- {
		maxIdx := 0
		for i := 1; i < size; i++ {
			if arr[i] > arr[maxIdx] {
				maxIdx = i
			}
		}
		if maxIdx != size-1 {
			flip(maxIdx)
			flip(size - 1)
		}
	}
	return arr
}

