func next_power_of_2(n int) int {
	if n > 0 && n&(n-1) == 0 {
		return n
	}
	if n <= 0 {
		return 1
	}
	count := 0
	for n != 0 {
		n >>= 1
		count++
	}
	return 1 << count
}

