func get_total_number_of_sequences(m int, n int) int {
	T := make([][]int, m+1)
	for i := range T {
		T[i] = make([]int, n+1)
	}
	for i := 0; i <= m; i++ {
		for j := 0; j <= n; j++ {
			if i == 0 || j == 0 {
				T[i][j] = 0
			} else if i < j {
				T[i][j] = 0
			} else if j == 1 {
				T[i][j] = i
			} else {
				T[i][j] = T[i-1][j] + T[i/2][j-1]
			}
		}
	}
	return T[m][n]
}

