func max_sum(arr []int) int {
	n := len(arr)
	if n == 0 {
		return 0
	}
	msibs := make([]int, n)
	copy(msibs, arr)
	for i := 1; i < n; i++ {
		for j := 0; j < i; j++ {
			if arr[i] > arr[j] && msibs[i] < msibs[j]+arr[i] {
				msibs[i] = msibs[j] + arr[i]
			}
		}
	}
	msdbs := make([]int, n)
	copy(msdbs, arr)
	for i := n - 2; i >= 0; i-- {
		for j := n - 1; j > i; j-- {
			if arr[i] > arr[j] && msdbs[i] < msdbs[j]+arr[i] {
				msdbs[i] = msdbs[j] + arr[i]
			}
		}
	}
	best := msibs[0] + msdbs[0] - arr[0]
	for i := 1; i < n; i++ {
		v := msibs[i] + msdbs[i] - arr[i]
		if v > best {
			best = v
		}
	}
	return best
}

