func count_no_of_ways(n int, k int) int {
	if n <= 0 {
		return 0
	}
	mod := 1000000007
	dp := make([]int, n+1)
	if n >= 1 {
		dp[1] = k
	}
	if n >= 2 {
		dp[2] = k * k
	}
	for i := 3; i <= n; i++ {
		dp[i] = ((k - 1) * (dp[i-1] + dp[i-2])) % mod
	}
	return dp[n]
}

