func max_sum_increasing_subseq(a []int, n int, index int, k int) int {
	dp := make([][]int, n)
	for i := range dp {
		dp[i] = make([]int, n)
	}
	for i := 0; i < n; i++ {
		if a[i] > a[0] {
			dp[0][i] = a[i] + a[0]
		} else {
			dp[0][i] = a[i]
		}
	}
	for i := 1; i < n; i++ {
		for j := 0; j < n; j++ {
			if a[j] > a[i] && j > i {
				if dp[i-1][i]+a[j] > dp[i-1][j] {
					dp[i][j] = dp[i-1][i] + a[j]
				} else {
					dp[i][j] = dp[i-1][j]
				}
			} else {
				dp[i][j] = dp[i-1][j]
			}
		}
	}
	return dp[index][k]
}

