import "sort"

func large_product(nums1 []int, nums2 []int, N int) []int {
	products := make([]int, 0, len(nums1)*len(nums2))
	for _, x := range nums1 {
		for _, y := range nums2 {
			products = append(products, x*y)
		}
	}
	sort.Sort(sort.Reverse(sort.IntSlice(products)))
	if N > len(products) {
		N = len(products)
	}
	return products[:N]
}

