package main

import (
	"container/heap"
)

type item408 struct {
	sum, i, j int
}

type pq408 []item408

func (p pq408) Len() int { return len(p) }
func (p pq408) Less(a, b int) bool {
	if p[a].sum != p[b].sum {
		return p[a].sum < p[b].sum
	}
	if p[a].i != p[b].i {
		return p[a].i < p[b].i
	}
	return p[a].j < p[b].j
}
func (p pq408) Swap(a, b int)       { p[a], p[b] = p[b], p[a] }
func (p *pq408) Push(x interface{}) { *p = append(*p, x.(item408)) }
func (p *pq408) Pop() interface{} {
	old := *p
	n := len(old)
	it := old[n-1]
	*p = old[:n-1]
	return it
}

func k_smallest_pairs(nums1 []int, nums2 []int, k int) [][]int {
	q := &pq408{}
	heap.Init(q)
	push := func(i, j int) {
		if i < len(nums1) && j < len(nums2) {
			heap.Push(q, item408{nums1[i] + nums2[j], i, j})
		}
	}
	push(0, 0)
	pairs := [][]int{}
	for q.Len() > 0 && len(pairs) < k {
		it := heap.Pop(q).(item408)
		i, j := it.i, it.j
		pairs = append(pairs, []int{nums1[i], nums2[j]})
		push(i, j+1)
		if j == 0 {
			push(i+1, 0)
		}
	}
	return pairs
}

