import "math"

func sumofFactors(n int) int {
	if n%2 != 0 {
		return 0
	}
	res := 1
	limit := int(math.Sqrt(float64(n)))
	for i := 2; i <= limit; i++ {
		count := 0
		currSum := 1
		currTerm := 1
		for n%i == 0 {
			count++
			n = n / i
			if i == 2 && count == 1 {
				currSum = 0
			}
			currTerm = currTerm * i
			currSum = currSum + currTerm
		}
		res = res * currSum
	}
	if n >= 2 {
		res = res * (1 + n)
	}
	return res
}

