func max_subarray_product(arr []int) int {
	n := len(arr)
	maxEndingHere := 1
	minEndingHere := 1
	maxSoFar := 0
	flag := 0
	for i := 0; i < n; i++ {
		if arr[i] > 0 {
			maxEndingHere = maxEndingHere * arr[i]
			minEndingHere = minEndingHere * arr[i]
			if minEndingHere > 1 {
				minEndingHere = 1
			}
			flag = 1
		} else if arr[i] == 0 {
			maxEndingHere = 1
			minEndingHere = 1
		} else {
			temp := maxEndingHere
			maxEndingHere = minEndingHere * arr[i]
			if maxEndingHere < 1 {
				maxEndingHere = 1
			}
			minEndingHere = temp * arr[i]
		}
		if maxSoFar < maxEndingHere {
			maxSoFar = maxEndingHere
		}
	}
	if flag == 0 && maxSoFar == 0 {
		return 0
	}
	return maxSoFar
}

