package main

// CPython-set-order emulation (int keys), needed to match reference's
// tuple(set(a) ^ set(b)) iteration order, which depends on CPython's open
// addressing hash table layout rather than sorted / insertion order.

const pySetMinSize = 8
const linearProbes = 9
const perturbShift = 5

type slotStatus int

const (
	slotEmpty slotStatus = iota
	slotActive
	slotDummy
)

type pyEntry struct {
	status slotStatus
	hash   uint64
	key    int64
}

type pySet struct {
	mask  uint64
	table []pyEntry
	fill  int
	used  int
}

func newPySet() *pySet {
	return &pySet{mask: pySetMinSize - 1, table: make([]pyEntry, pySetMinSize)}
}

func pyHash(n int64) uint64 {
	if n == -1 {
		var neg2 int64 = -2
		return uint64(neg2)
	}
	return uint64(n)
}

func (s *pySet) insertClean(hash uint64, key int64) {
	mask := s.mask
	i := hash & mask
	perturb := hash
	for s.table[i].status != slotEmpty {
		perturb >>= perturbShift
		i = (i*5 + 1 + perturb) & mask
	}
	s.table[i] = pyEntry{status: slotActive, hash: hash, key: key}
}

func (s *pySet) resize(minused int) {
	newsize := pySetMinSize
	for newsize <= minused {
		newsize <<= 1
	}
	old := s.table
	s.table = make([]pyEntry, newsize)
	s.mask = uint64(newsize - 1)
	s.fill = s.used
	for _, e := range old {
		if e.status == slotActive {
			s.insertClean(e.hash, e.key)
		}
	}
}

func (s *pySet) add(key int64) {
	hash := pyHash(key)
	mask := s.mask
	i := hash & mask
	perturb := hash
	freeslot := int64(-1)
	for {
		probes := uint64(0)
		if i+linearProbes <= mask {
			probes = linearProbes
		}
		j := i
		for p := uint64(0); p <= probes; p++ {
			e := &s.table[j]
			if e.status == slotEmpty {
				if freeslot != -1 {
					s.table[freeslot] = pyEntry{status: slotActive, hash: hash, key: key}
					s.used++
					return
				}
				s.table[j] = pyEntry{status: slotActive, hash: hash, key: key}
				s.fill++
				s.used++
				if uint64(s.fill)*5 >= mask*3 {
					minused := s.used * 4
					if s.used > 50000 {
						minused = s.used * 2
					}
					s.resize(minused)
				}
				return
			}
			if e.status == slotActive && e.hash == hash && e.key == key {
				return
			}
			if e.status == slotDummy && freeslot == -1 {
				freeslot = int64(j)
			}
			j++
		}
		perturb >>= perturbShift
		i = (i*5 + 1 + perturb) & mask
	}
}

func (s *pySet) discard(key int64) {
	hash := pyHash(key)
	mask := s.mask
	i := hash & mask
	perturb := hash
	for {
		probes := uint64(0)
		if i+linearProbes <= mask {
			probes = linearProbes
		}
		j := i
		for p := uint64(0); p <= probes; p++ {
			e := &s.table[j]
			if e.status == slotEmpty {
				return
			}
			if e.status == slotActive && e.hash == hash && e.key == key {
				e.status = slotDummy
				s.used--
				return
			}
			j++
		}
		perturb >>= perturbShift
		i = (i*5 + 1 + perturb) & mask
	}
}

func (s *pySet) contains(key int64) bool {
	hash := pyHash(key)
	mask := s.mask
	i := hash & mask
	perturb := hash
	for {
		probes := uint64(0)
		if i+linearProbes <= mask {
			probes = linearProbes
		}
		j := i
		for p := uint64(0); p <= probes; p++ {
			e := &s.table[j]
			if e.status == slotEmpty {
				return false
			}
			if e.status == slotActive && e.hash == hash && e.key == key {
				return true
			}
			j++
		}
		perturb >>= perturbShift
		i = (i*5 + 1 + perturb) & mask
	}
}

func (s *pySet) copyOf() *pySet {
	ns := &pySet{mask: s.mask, table: make([]pyEntry, len(s.table)), fill: s.fill, used: s.used}
	copy(ns.table, s.table)
	return ns
}

func (s *pySet) items() []int64 {
	res := []int64{}
	for _, e := range s.table {
		if e.status == slotActive {
			res = append(res, e.key)
		}
	}
	return res
}

func buildPySet(vals []int64) *pySet {
	s := newPySet()
	for _, v := range vals {
		s.add(v)
	}
	return s
}

func symmetricDifference(a, b *pySet) *pySet {
	result := a.copyOf()
	for _, key := range b.items() {
		if result.contains(key) {
			result.discard(key)
		} else {
			result.add(key)
		}
	}
	return result
}

func find_dissimilar(test_tup1 []interface{}, test_tup2 []interface{}) []interface{} {
	toI64 := func(xs []interface{}) []int64 {
		out := make([]int64, len(xs))
		for i, x := range xs {
			switch v := x.(type) {
			case int:
				out[i] = int64(v)
			case int64:
				out[i] = v
			case float64:
				out[i] = int64(v)
			}
		}
		return out
	}
	a := buildPySet(toI64(test_tup1))
	b := buildPySet(toI64(test_tup2))
	res := symmetricDifference(a, b)
	items := res.items()
	out := make([]interface{}, len(items))
	for i, v := range items {
		out[i] = int(v)
	}
	return out
}

