func binomial_Coeff(n int, k int) int {
	C := make([]int, k+1)
	C[0] = 1
	for i := 1; i <= n; i++ {
		top := k
		if i < top {
			top = i
		}
		for j := top; j > 0; j-- {
			C[j] = C[j] + C[j-1]
