// average_tuple mirrors the classic MBPP reference which, despite the
// "average value for each sublist" description, actually zips the sublists
// column-wise (like Python's zip(*nums)) and averages each column.
func average_tuple(nums [][]int) []float64 {
	if len(nums) == 0 {
		return []float64{}
	}
	cols := len(nums[0])
	for _, sub := range nums {
		if len(sub) < cols {
			cols = len(sub)
		}
	}
	result := make([]float64, cols)
	for c := 0; c < cols; c++ {
		sum := 0.0
		for _, sub := range nums {
			sum += float64(sub[c])
		}
		result[c] = sum / float64(len(nums))
	}
	return result
}

