package main

func heap_sort(iterable []int) []int {
	h := make([]int, len(iterable))
	copy(h, iterable)
	// heapify (min-heap)
	n := len(h)
	for i := n/2 - 1; i >= 0; i-- {
		siftDown(h, i, n)
	}
	result := make([]int, 0, n)
	for size := n; size > 0; size-- {
		result = append(result, h[0])
		h[0] = h[size-1]
		siftDown(h, 0, size-1)
	}
	return result
}

func siftDown(h []int, i int, size int) {
	for {
		smallest := i
		l := 2*i + 1
		r := 2*i + 2
		if l < size && h[l] < h[smallest] {
			smallest = l
		}
		if r < size && h[r] < h[smallest] {
			smallest = r
		}
		if smallest == i {
			return
		}
		h[i], h[smallest] = h[smallest], h[i]
		i = smallest
	}
}

