func maxAverageOfPath(cost [][]int) float64 {
	n := len(cost)
	dp := make([][]int, n+1)
	for i := range dp {
		dp[i] = make([]int, n+1)
	}
	dp[0][0] = cost[0][0]
	for i := 1; i < n; i++ {
		dp[i][0] = dp[i-1][0] + cost[i][0]
	}
	for j := 1; j < n; j++ {
		dp[0][j] = dp[0][j-1] + cost[0][j]
	}
	for i := 1; i < n; i++ {
		for j := 1; j < n; j++ {
			best := dp[i-1][j]
			if dp[i][j-1] > best {
				best = dp[i][j-1]
			}
			dp[i][j] = best + cost[i][j]
		}
	}
	return float64(dp[n-1][n-1]) / float64(2*n-1)
}

