func lcs_of_three(X string, Y string, Z string) int {
	m := len(X)
	n := len(Y)
	o := len(Z)
	L := make([][][]int, m+1)
	for i := 0; i <= m; i++ {
		L[i] = make([][]int, n+1)
		for j := 0; j <= n; j++ {
			L[i][j] = make([]int, o+1)
		}
	}
	for i := 1; i <= m; i++ {
		for j := 1; j <= n; j++ {
			for k := 1; k <= o; k++ {
				if X[i-1] == Y[j-1] && X[i-1] == Z[k-1] {
