import "strings"

// Replicates Python's re.sub(r"(\w)([A-Z])", r"\1 \2", str1) with
// non-overlapping left-to-right matching semantics.
func capital_words_spaces(str1 string) string {
	isWord := func(b byte) bool {
		return b == '_' || (b >= '0' && b <= '9') || (b >= 'a' && b <= 'z') || (b >= 'A' && b <= 'Z')
	}
	var sb strings.Builder
	i := 0
	for i < len(str1) {
		if i+1 < len(str1) && isWord(str1[i]) && str1[i+1] >= 'A' && str1[i+1] <= 'Z' {
			sb.WriteByte(str1[i])
			sb.WriteByte(' ')
			sb.WriteByte(str1[i+1])
			i += 2
		} else {
			sb.WriteByte(str1[i])
			i++
		}
	}
	return sb.String()
}

