package main

// Diff replicates Python's
//   list(set(li1) - set(li2)) + list(set(li2) - set(li1))
// including the element order produced by CPython's set implementation
// (open addressing, LINEAR_PROBES=9, perturb probing, 3/5 load factor,
// set_difference's copy-and-discard fast path, and dummy-slot handling).

const (
	slotUnused int8 = 0
	slotActive int8 = 1
	slotDummy  int8 = 2
)

const linearProbes = 9
const perturbShift = 5

type pySetEntry struct {
	state int8
	hash  int64
	key   int
}

type pySet struct {
	table []pySetEntry
	mask  uint64
	fill  int
	used  int
}

func newPySet() *pySet {
	return &pySet{table: make([]pySetEntry, 8), mask: 7}
}

func pyIntHash(x int) int64 {
	const modulus = (1 << 61) - 1
	v := int64(x)
	neg := v < 0
	if neg {
		v = -v
	}
	h := v % modulus
	if neg {
		h = -h
	}
	if h == -1 {
		h = -2
	}
	return h
}

// set_lookkey: returns the matching active entry or nil if absent.
func (s *pySet) lookkey(key int, hash int64) *pySetEntry {
	mask := s.mask
	i := uint64(hash) & mask
	perturb := uint64(hash)
	for {
		probes := 0
		if i+linearProbes <= mask {
			probes = linearProbes
		}
		j := i
		for {
			entry := &s.table[j]
			if entry.state == slotUnused {
				return nil
			}
			if entry.state == slotActive && entry.hash == hash && entry.key == key {
				return entry
			}
			if probes == 0 {
				break
			}
			probes--
			j++
		}
		perturb >>= perturbShift
		i = (i*5 + 1 + perturb) & mask
	}
}

// set_add_entry
func (s *pySet) addEntry(key int, hash int64) {
	mask := s.mask
	i := uint64(hash) & mask
	perturb := uint64(hash)
	var freeslot *pySetEntry
	var entry *pySetEntry
	for entry == nil {
		probes := 0
		if i+linearProbes <= mask {
			probes = linearProbes
		}
		j := i
		for {
			e := &s.table[j]
			if e.state == slotUnused {
				entry = e
				break
			}
			if e.state == slotActive && e.hash == hash && e.key == key {
				return // already present
			}
			if e.state == slotDummy {
				freeslot = e
			}
			if probes == 0 {
				break
			}
			probes--
			j++
		}
		if entry != nil {
			break
		}
		perturb >>= perturbShift
		i = (i*5 + 1 + perturb) & mask
	}
	if freeslot != nil {
		s.used++
		freeslot.state = slotActive
		freeslot.key = key
		freeslot.hash = hash
		return
	}
	s.fill++
	s.used++
	entry.state = slotActive
	entry.key = key
	entry.hash = hash
	if uint64(s.fill)*5 < mask*3 {
		return
	}
	grow := s.used * 4
	if s.used > 50000 {
		grow = s.used * 2
	}
	s.resize(grow)
}

func (s *pySet) add(key int) {
	s.addEntry(key, pyIntHash(key))
}

// set_discard_entry: mark as dummy (fill unchanged, used--).
func (s *pySet) discardEntry(key int, hash int64) {
	e := s.lookkey(key, hash)
	if e != nil {
		e.state = slotDummy
		e.hash = 0
		e.key = 0
		s.used--
	}
}

// set_insert_clean: insertion into a table known to have no dummies
// and no duplicate of key.
func (s *pySet) insertClean(key int, hash int64) {
	mask := s.mask
	i := uint64(hash) & mask
	perturb := uint64(hash)
	for {
		entry := &s.table[i]
		if entry.state == slotUnused {
			entry.state = slotActive
			entry.hash = hash
			entry.key = key
			return
		}
		if i+linearProbes <= mask {
			for j := uint64(1); j <= linearProbes; j++ {
				entry = &s.table[i+j]
				if entry.state == slotUnused {
					entry.state = slotActive
					entry.hash = hash
					entry.key = key
					return
				}
			}
		}
		perturb >>= perturbShift
		i = (i*5 + 1 + perturb) & mask
	}
}

// set_table_resize
func (s *pySet) resize(minused int) {
	newsize := uint64(8)
	for newsize <= uint64(minused) {
		newsize <<= 1
	}
	old := s.table
	s.table = make([]pySetEntry, newsize)
	s.mask = newsize - 1
	s.fill = s.used
	for idx := range old {
		if old[idx].state == slotActive {
			s.insertClean(old[idx].key, old[idx].hash)
		}
	}
}

// iteration order: table scan, active entries only (set_next).
func (s *pySet) elems() []int {
	out := make([]int, 0, s.used)
	for i := range s.table {
		if s.table[i].state == slotActive {
			out = append(out, s.table[i].key)
		}
	}
	return out
}

func pySetFrom(li []int) *pySet {
	s := newPySet()
	for _, v := range li {
		s.add(v)
	}
	return s
}

// set_copy via set_merge into a fresh empty set.
func pySetCopy(other *pySet) *pySet {
	so := newPySet()
	// One big resize at the start.
	if uint64(so.fill+other.used)*5 >= so.mask*3 {
		so.resize((so.used + other.used) * 2)
	}
	// Direct positional copy when table sizes match and other has no dummies.
	if so.fill == 0 && so.mask == other.mask && other.fill == other.used {
		copy(so.table, other.table)
		so.fill = other.fill
		so.used = other.used
		return so
	}
	// Empty destination: insert_clean in the other's table order.
	if so.fill == 0 {
		so.fill = other.used
		so.used = other.used
		for i := range other.table {
			e := &other.table[i]
			if e.state == slotActive {
				so.insertClean(e.key, e.hash)
			}
		}
		return so
	}
	for i := range other.table {
		e := &other.table[i]
		if e.state == slotActive {
			so.addEntry(e.key, e.hash)
		}
	}
	return so
}

// set_difference_update_internal (other is always a set here).
func (s *pySet) differenceUpdate(other *pySet) {
	if s.used == 0 {
		return
	}
	for i := range other.table {
		e := &other.table[i]
		if e.state == slotActive {
			s.discardEntry(e.key, e.hash)
		}
	}
	// If more than 1/4th are dummies, resize them away.
	if uint64(s.fill-s.used) < s.mask>>2 {
		return
	}
	grow := s.used * 4
	if s.used > 50000 {
		grow = s.used * 2
	}
	s.resize(grow)
}

// set_difference
func pySetDifference(a, b *pySet) *pySet {
	if a.used>>2 > b.used {
		// set_copy_and_difference
		result := pySetCopy(a)
		result.differenceUpdate(b)
		return result
	}
	res := newPySet()
	for i := range a.table {
		e := &a.table[i]
		if e.state == slotActive && b.lookkey(e.key, e.hash) == nil {
			res.addEntry(e.key, e.hash)
		}
	}
	return res
}

func Diff(li1 []int, li2 []int) []int {
	s1 := pySetFrom(li1)
	s2 := pySetFrom(li2)
	out := make([]int, 0)
	out = append(out, pySetDifference(s1, s2).elems()...)
	out = append(out, pySetDifference(s2, s1).elems()...)
	return out
}

