package main

func check_expression(exp string) bool {
	if len(exp)&1 == 1 {
		return false
	}
	stack := make([]byte, 0, len(exp))
	for i := 0; i < len(exp); i++ {
		ch := exp[i]
		if ch == '(' || ch == '{' || ch == '[' {
			stack = append(stack, ch)
		}
		if ch == ')' || ch == '}' || ch == ']' {
			if len(stack) == 0 {
				return false
			}
			top := stack[len(stack)-1]
			stack = stack[:len(stack)-1]
			if (top == '(' && ch != ')') || (top == '{' && ch != '}') || (top == '[' && ch != ']') {
				return false
			}
		}
	}
	return len(stack) == 0
}

