import "math"

func rgb_to_hsv(r int, g int, b int) []float64 {
	rf := float64(r) / 255.0
	gf := float64(g) / 255.0
	bf := float64(b) / 255.0
	mx := math.Max(rf, math.Max(gf, bf))
	mn := math.Min(rf, math.Min(gf, bf))
	df := mx - mn
	var h float64
	if mx == mn {
		h = 0
	} else if mx == rf {
		h = math.Mod(60*((gf-bf)/df)+360, 360)
	} else if mx == gf {
		h = math.Mod(60*((bf-rf)/df)+120, 360)
	} else {
		h = math.Mod(60*((rf-gf)/df)+240, 360)
	}
	if h < 0 {
		h += 360
	}
	var s float64
	if mx == 0 {
		s = 0
	} else {
		s = (df / mx) * 100
	}
	v := mx * 100
	return []float64{h, s, v}
}

