import java.util.*;
import java.lang.reflect.*;
import java.security.*;
import java.math.*;
import java.io.*;
import java.util.stream.*;

class Solution {
    public static long nextSmallestPalindrome(long num) {
        if (num < 0) {
            return 0;
        }
        long n = num + 1;
        char[] p = Long.toString(n).toCharArray();
        int len = p.length;
        // Mirror the left half onto the right half.
        for (int i = 0; i < len / 2; i++) {
            p[len - 1 - i] = p[i];
        }
        long mirrored = Long.parseLong(new String(p));
        if (mirrored >= n) {
            return mirrored;
        }
        // Mirrored value is too small: increment the left half (including
        // the middle digit) and mirror again.
        int i = (len - 1) / 2;
        while (i >= 0 && p[i] == '9') {
            p[i] = '0';
            i--;
        }
        if (i < 0) {
            // All nines in the left half: result is 10^len + 1.
            long result = 1;
            for (int j = 0; j < len; j++) {
                result *= 10;
            }
            return result + 1;
        }
        p[i]++;
        for (int j = 0; j < len / 2; j++) {
            p[len - 1 - j] = p[j];
        }
        return Long.parseLong(new String(p));
    }
}

