import java.util.*;
import java.lang.reflect.*;
import java.security.*;
import java.math.*;
import java.io.*;
import java.util.stream.*;

class Solution {
    public static long oddEquivalent(String s, long n) {
        int len = s.length();
        if (len == 0 || n <= 0) {
            return 0L;
        }
        long onesTotal = 0;
        for (int i = 0; i < len; i++) {
            if (s.charAt(i) == '1') {
                onesTotal++;
            }
        }
        long fullCycles = n / len;
        int remainder = (int) (n % len);
        long count = fullCycles * onesTotal;
        for (int i = 0; i < remainder; i++) {
            if (s.charAt(i) == '1') {
                count++;
            }
        }
        return count;
    }
}

