class Solution {
    public static long amicableNumbersSum(long limit) {
        if (limit < 1) {
            return 0L;
        }
        long total = 0;
        for (long num = 2; num <= limit; num++) {
            long s1 = properDivisorSum(num);
            if (s1 != num && properDivisorSum(s1) == num) {
                total += num;
            }
        }
        return total;
    }

    private static long properDivisorSum(long m) {
        if (m <= 1) {
            return 0L;
        }
        long sum = 1L;
        for (long i = 2; i * i <= m; i++) {
            if (m % i == 0) {
                sum += i;
                long other = m / i;
                if (other != i) {
                    sum += other;
                }
            }
        }
        return sum;
    }
}

