import java.util.*;
import java.lang.reflect.*;
import java.security.*;
import java.math.*;
import java.io.*;
import java.util.stream.*;

class Solution {
    public static long sum(long a, long b) {
        if (a <= 0 || b <= 0) {
            return 0L;
        }
        long g = gcd(a, b);
        long total = 0;
        for (long i = 1; i * i <= g; i++) {
            if (g % i == 0) {
                total += i;
                long other = g / i;
                if (other != i) {
                    total += other;
                }
            }
        }
        long smaller = Math.min(a, b);
        if (g == smaller) {
            total -= g;
        }
        return total;
    }

    private static long gcd(long x, long y) {
        while (y != 0) {
            long t = x % y;
            x = y;
            y = t;
        }
        return x;
    }
}

