import java.util.*;
import java.lang.reflect.*;
import java.security.*;
import java.math.*;
import java.io.*;
import java.util.stream.*;

class Solution {
    public static boolean magicSquareTest(ArrayList<ArrayList<Long>> my_matrix) {
        int n = my_matrix.size();
        if (n == 0) {
            return true;
        }
        HashSet<Long> sums = new HashSet<Long>();
        for (ArrayList<Long> row : my_matrix) {
            long s = 0;
            for (Long v : row) {
                s += v;
            }
            sums.add(s);
        }
        int cols = my_matrix.get(0).size();
        for (int c = 0; c < cols; c++) {
            long s = 0;
            for (int r = 0; r < n; r++) {
                s += my_matrix.get(r).get(c);
            }
            sums.add(s);
        }
        long diag1 = 0;
        long diag2 = 0;
        for (int i = 0; i < n; i++) {
            diag1 += my_matrix.get(i).get(i);
            diag2 += my_matrix.get(i).get(n - 1 - i);
        }
        sums.add(diag1);
        sums.add(diag2);
        return sums.size() <= 1;
    }
}

