import java.security.*;
import java.math.*;
import java.io.*;
import java.util.stream.*;

class Solution {
    public static ArrayList<Long> pancakeSort(ArrayList<Long> nums) {
        ArrayList<Long> arr = new ArrayList<>(nums);
        for (int currSize = arr.size(); currSize > 1; currSize--) {
            int maxIdx = 0;
            for (int i = 1; i < currSize; i++) {
                if (arr.get(i) > arr.get(maxIdx)) {
                    maxIdx = i;
                }
            }
            if (maxIdx != currSize - 1) {
                Collections.reverse(arr.subList(0, maxIdx + 1));
                Collections.reverse(arr.subList(0, currSize));
            }
        }
        return arr;
    }
}

