import java.util.*;
import java.lang.reflect.*;
import java.security.*;
import java.math.*;
import java.io.*;
import java.util.stream.*;

class Solution {
    public static long maxSum(ArrayList<Long> arr) {
        int n = arr.size();
        if (n == 0) {
            return 0;
        }
        long[] a = new long[n];
        for (int i = 0; i < n; i++) {
            a[i] = arr.get(i);
        }
        long[] inc = a.clone();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < i; j++) {
                if (a[i] > a[j] && inc[i] < inc[j] + a[i]) {
                    inc[i] = inc[j] + a[i];
                }
            }
        }
        long[] dec = a.clone();
        for (int i = n - 2; i >= 0; i--) {
            for (int j = n - 1; j > i; j--) {
                if (a[i] > a[j] && dec[i] < dec[j] + a[i]) {
                    dec[i] = dec[j] + a[i];
                }
            }
        }
        long best = Long.MIN_VALUE;
        for (int i = 0; i < n; i++) {
            best = Math.max(best, inc[i] + dec[i] - a[i]);
        }
        return best;
    }
}

