class Solution {
    public static long lps(String str) {
        int n = str.length();
        if (n == 0) {
            return 0;
        }
        long[][] L = new long[n][n];
        for (int i = 0; i < n; i++) {
            L[i][i] = 1;
        }
        for (int cl = 2; cl <= n; cl++) {
            for (int i = 0; i <= n - cl; i++) {
