class Solution {
    public static ArrayList<ArrayList<String>> combinationsColors(ArrayList<String> l, long n) {
        ArrayList<ArrayList<String>> result = new ArrayList<ArrayList<String>>();
        int k = (int) n;
        if (k <= 0) {
            result.add(new ArrayList<String>());
            return result;
        }
        if (l.isEmpty()) {
            return result;
        }
        build(l, k, 0, new ArrayList<String>(), result);
        return result;
    }

    private static void build(ArrayList<String> l, int k, int start, ArrayList<String> current, ArrayList<ArrayList<String>> result) {
        if (current.size() == k) {
            result.add(new ArrayList<String>(current));
            return;
        }
        for (int i = start; i < l.size(); i++) {
            current.add(l.get(i));
            build(l, k, i, current, result);
            current.remove(current.size() - 1);
        }
    }
}

