import java.util.*;
import java.lang.reflect.*;
import java.security.*;
import java.math.*;
import java.io.*;
import java.util.stream.*;

class Solution {
    public static long countNoOfWays(long n, long k) {
        final long mod = 1000000007L;
        if (n <= 0) {
            return 0;
        }
        if (n == 1) {
            return k;
        }
        long dpPrev2 = k;       // dp[1]
        long dpPrev1 = k * k;   // dp[2]
        if (n == 2) {
            return dpPrev1;
        }
        long dpCur = dpPrev1;
        for (long i = 3; i <= n; i++) {
            dpCur = ((k - 1) * (dpPrev1 + dpPrev2)) % mod;
            dpPrev2 = dpPrev1;
            dpPrev1 = dpCur;
        }
        return dpCur;
    }
}

