import java.security.*;
import java.math.*;
import java.io.*;
import java.util.stream.*;

class Solution {
    public static long findElement(ArrayList<Long> arr, ArrayList<ArrayList<Long>> ranges, long rotations, long index) {
        for (long i = rotations - 1; i >= 0; i--) {
            ArrayList<Long> range = ranges.get((int) i);
            long left = range.get(0);
            long right = range.get(1);
            if (left <= index && right >= index) {
                if (index == left) {
                    index = right;
                } else {
                    index = index - 1;
                }
            }
        }
        return arr.get((int) index);
    }
}

