import java.util.*;
import java.lang.reflect.*;
import java.security.*;
import java.math.*;
import java.io.*;
import java.util.stream.*;

class Solution {
    public static long maxSumIncreasingSubseq(ArrayList<Long> a, long n, long index, long k) {
        int nn = (int) n;
        long[][] dp = new long[nn][nn];
        for (int i = 0; i < nn; i++) {
            if (a.get(i) > a.get(0)) {
                dp[0][i] = a.get(i) + a.get(0);
            } else {
                dp[0][i] = a.get(i);
            }
        }
        for (int i = 1; i < nn; i++) {
            for (int j = 0; j < nn; j++) {
                if (a.get(j) > a.get(i) && j > i) {
                    if (dp[i - 1][i] + a.get(j) > dp[i - 1][j]) {
                        dp[i][j] = dp[i - 1][i] + a.get(j);
                    } else {
                        dp[i][j] = dp[i - 1][j];
                    }
                } else {
                    dp[i][j] = dp[i - 1][j];
                }
            }
        }
        return dp[(int) index][(int) k];
    }
}

