import java.util.*;
import java.lang.reflect.*;
import java.security.*;
import java.math.*;
import java.io.*;
import java.util.stream.*;

class Solution {
    public static ArrayList<ArrayList<Long>> kSmallestPairs(ArrayList<Long> nums1, ArrayList<Long> nums2, long k) {
        PriorityQueue<long[]> queue = new PriorityQueue<>((a, b) -> {
            if (a[0] != b[0]) return Long.compare(a[0], b[0]);
            if (a[1] != b[1]) return Long.compare(a[1], b[1]);
            return Long.compare(a[2], b[2]);
        });

        int n1 = nums1.size();
        int n2 = nums2.size();

        ArrayList<ArrayList<Long>> pairs = new ArrayList<>();

        if (n1 > 0 && n2 > 0) {
            queue.offer(new long[]{nums1.get(0) + nums2.get(0), 0, 0});
        }

        while (!queue.isEmpty() && pairs.size() < k) {
            long[] top = queue.poll();
            int i = (int) top[1];
            int j = (int) top[2];
            ArrayList<Long> pair = new ArrayList<>();
            pair.add(nums1.get(i));
            pair.add(nums2.get(j));
            pairs.add(pair);

            if (i < n1 && j + 1 < n2) {
                queue.offer(new long[]{nums1.get(i) + nums2.get(j + 1), i, j + 1});
            }
            if (j == 0 && i + 1 < n1) {
                queue.offer(new long[]{nums1.get(i + 1) + nums2.get(0), i + 1, 0});
            }
        }
        return pairs;
    }
}

