import java.util.*;
import java.lang.reflect.*;
import java.security.*;
import java.math.*;
import java.io.*;
import java.util.stream.*;

class Solution {
    public static ArrayList<Long> shellSort(ArrayList<Long> my_list) {
        int n = my_list.size();
        int gap = n / 2;
        while (gap > 0) {
            for (int i = gap; i < n; i++) {
                long currentItem = my_list.get(i);
                int j = i;
                while (j >= gap && my_list.get(j - gap) > currentItem) {
                    my_list.set(j, my_list.get(j - gap));
                    j -= gap;
                }
                my_list.set(j, currentItem);
            }
            gap /= 2;
        }
        return my_list;
    }
}

