import java.util.*;
import java.lang.reflect.*;
import java.security.*;
import java.math.*;
import java.io.*;
import java.util.stream.*;

class Solution {
    private static long binomialCoeff(long n, long k) {
        int kk = (int) k;
        long[] C = new long[kk + 1];
        C[0] = 1;
        for (long i = 1; i <= n; i++) {
            for (int j = (int) Math.min(i, kk); j >= 1; j--) {
                C[j] = C[j] + C[j - 1];
            }
        }
        return C[kk];
    }

    public static long sumOfProduct(long n) {
        return binomialCoeff(2 * n, n - 1);
    }
}

