import java.util.*;
import java.lang.reflect.*;
import java.security.*;
import java.math.*;
import java.io.*;
import java.util.stream.*;

class Solution {
    private static long ipow(long base, long exp) {
        long result = 1;
        for (long e = 0; e < exp; e++) result *= base;
        return result;
    }

    public static boolean armstrongNumber(long number) {
        long sum = 0;
        long times = 0;
        long temp = number;
        while (temp > 0) {
            times = times + 1;
            temp = temp / 10;
        }
        temp = number;
        while (temp > 0) {
            long reminder = temp % 10;
            sum = sum + ipow(reminder, times);
            temp = temp / 10;
        }
        return number == sum;
    }
}

