class Solution {
    public static ArrayList<Long> getLudic(long n) {
        int nn = (int) n;
        ArrayList<Long> ludics = new ArrayList<>();
        for (long i = 1; i <= nn; i++) ludics.add(i);
        int index = 1;
        while (index != ludics.size()) {
            long firstLudic = ludics.get(index);
            int removeIndex = (int) (index + firstLudic);
