import java.util.*;
import java.lang.reflect.*;
import java.security.*;
import java.math.*;
import java.io.*;
import java.util.stream.*;

class Solution {
    public static float getMedian(ArrayList<Long> arr1, ArrayList<Long> arr2, long n) {
        int nn = (int) n;
        int i = 0, j = 0;
        long m1 = -1, m2 = -1;
        int count = 0;
        while (count < nn + 1) {
            count += 1;
            if (i == nn) {
                m1 = m2;
                m2 = arr2.get(0);
                break;
            } else if (j == nn) {
                m1 = m2;
                m2 = arr1.get(0);
                break;
            }
            if (arr1.get(i) <= arr2.get(j)) {
                m1 = m2;
                m2 = arr1.get(i);
                i += 1;
            } else {
                m1 = m2;
                m2 = arr2.get(j);
                j += 1;
            }
        }
        return (m1 + m2) / 2.0f;
    }
}

