import java.security.*;
import java.math.*;
import java.io.*;
import java.util.stream.*;

class Solution {
    public static long findFirstMissing(ArrayList<Long> array) {
        int start = 0, end = array.size() - 1;
        while (start <= end) {
            if (array.get(start) != start) {
                return start;
            }
            int mid = (start + end) / 2;
            if (array.get(mid) == mid) {
                start = mid + 1;
            } else {
                end = mid;
            }
        }
        return end + 1;
    }
}

