import java.util.*;
import java.lang.reflect.*;
import java.security.*;
import java.math.*;
import java.io.*;
import java.util.stream.*;

class Solution {
    public static float maxAverageOfPath(ArrayList<ArrayList<Long>> cost) {
        int N = cost.size();
        long[][] dp = new long[N][N];
        dp[0][0] = cost.get(0).get(0);
        for (int i = 1; i < N; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }
        for (int j = 1; j < N; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }
        for (int i = 1; i < N; i++) {
            for (int j = 1; j < N; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
            }
        }
        return (float) dp[N - 1][N - 1] / (2 * N - 1);
    }
}

