import java.util.*;
import java.lang.reflect.*;
import java.security.*;
import java.math.*;
import java.io.*;
import java.util.stream.*;

class Solution {
    public static ArrayList<Long> rotateRight(ArrayList<Long> list, long m) {
        int n = list.size();
        // Python: list1[-(m):] + list1[:-(m)]
        // For m > 0 this slices at index max(0, n - m); for m == 0 the
        // concatenation is (whole list) + (empty), which equals the same result.
        long cutL = n - m;
        if (cutL < 0) cutL = 0;
        if (cutL > n) cutL = n;
        int cut = (int) cutL;
        ArrayList<Long> result = new ArrayList<>();
        if (m == 0) {
            result.addAll(list);
            return result;
        }
        result.addAll(list.subList(cut, n));
        result.addAll(list.subList(0, cut));
        return result;
    }
}

