import java.util.*;
import java.lang.reflect.*;
import java.security.*;
import java.math.*;
import java.io.*;
import java.util.stream.*;

class Solution {
    public static long lcsOfThree(String X, String Y, String Z) {
        int m = X.length(), n = Y.length(), o = Z.length();
        long[][][] L = new long[m + 1][n + 1][o + 1];
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                for (int k = 1; k <= o; k++) {
                    if (X.charAt(i - 1) == Y.charAt(j - 1) && X.charAt(i - 1) == Z.charAt(k - 1)) {
                        L[i][j][k] = L[i - 1][j - 1][k - 1] + 1;
                    } else {
                        L[i][j][k] = Math.max(Math.max(L[i - 1][j][k], L[i][j - 1][k]), L[i][j][k - 1]);
                    }
                }
            }
        }
        return L[m][n][o];
    }
}

