import java.util.*;
import java.lang.reflect.*;
import java.security.*;
import java.math.*;
import java.io.*;
import java.util.stream.*;

class Solution {

    // Faithful simulation of CPython's setobject for long keys, so that
    // list(set(li1) - set(li2)) + list(set(li2) - set(li1)) reproduces the
    // exact element order of the original Python reference solution.
    private static final int LINEAR_PROBES = 9;
    private static final int PERTURB_SHIFT = 5;

    private static final class PySet {
        static final byte EMPTY = 0;
        static final byte ACTIVE = 1;
        static final byte DUMMY = 2;

        long[] keys;
        long[] hashes;
        byte[] state;
        int mask;
        int fill;  // active + dummy entries
        int used;  // active entries

        PySet() {
            alloc(8);
        }

        private void alloc(int size) {
            keys = new long[size];
            hashes = new long[size];
            state = new byte[size];
            mask = size - 1;
            fill = 0;
            used = 0;
        }

        void add(long key) {
            addEntry(key, pyHash(key));
        }

        void addEntry(long key, long hash) {
            long maskL = mask;
            long i = hash & maskL;
            long perturb = hash;
            int freeslot = -1;
            int slot;

            findSlot:
            while (true) {
                int idx = (int) i;
                int probes = (i + LINEAR_PROBES <= maskL) ? LINEAR_PROBES : 0;
                for (int p = 0; ; p++) {
                    if (state[idx] == EMPTY) {
                        slot = idx;
                        break findSlot;
                    }
                    if (state[idx] == ACTIVE && hashes[idx] == hash && keys[idx] == key) {
                        return; // already present
                    }
                    if (state[idx] == DUMMY && freeslot == -1) {
                        freeslot = idx;
                    }
                    if (p == probes) {
                        break;
                    }
                    idx++;
                }
                perturb >>>= PERTURB_SHIFT;
                i = (i * 5 + 1 + perturb) & maskL;
            }

            if (freeslot != -1) {
                used++;
                keys[freeslot] = key;
                hashes[freeslot] = hash;
                state[freeslot] = ACTIVE;
                return;
            }
            fill++;
            used++;
            keys[slot] = key;
            hashes[slot] = hash;
            state[slot] = ACTIVE;
            if ((long) fill * 5 < maskL * 3) {
                return;
            }
            resize(used > 50000 ? used * 2 : used * 4);
        }

        void resize(int minused) {
            int newsize = 8;
            while (newsize <= minused) {
                newsize <<= 1;
            }
            long[] oldKeys = keys;
            long[] oldHashes = hashes;
            byte[] oldState = state;
            alloc(newsize);
            int count = 0;
            for (int idx = 0; idx < oldState.length; idx++) {
                if (oldState[idx] == ACTIVE) {
                    insertClean(oldKeys[idx], oldHashes[idx]);
                    count++;
                }
            }
            fill = count;
            used = count;
        }

        void insertClean(long key, long hash) {
            long maskL = mask;
            long perturb = hash;
            long i = hash & maskL;
            while (true) {
                int idx = (int) i;
                if (state[idx] == EMPTY) {
                    keys[idx] = key;
                    hashes[idx] = hash;
                    state[idx] = ACTIVE;
                    return;
                }
                if (i + LINEAR_PROBES <= maskL) {
                    for (int j = 0; j < LINEAR_PROBES; j++) {
                        idx++;
                        if (state[idx] == EMPTY) {
                            keys[idx] = key;
                            hashes[idx] = hash;
                            state[idx] = ACTIVE;
                            return;
                        }
                    }
                }
                perturb >>>= PERTURB_SHIFT;
                i = (i * 5 + 1 + perturb) & maskL;
            }
        }

        // Returns slot index of the active matching entry, or -1 if not found.
        int lookup(long key, long hash) {
            long maskL = mask;
            long i = hash & maskL;
            long perturb = hash;
            while (true) {
                int idx = (int) i;
                int probes = (i + LINEAR_PROBES <= maskL) ? LINEAR_PROBES : 0;
                for (int p = 0; ; p++) {
                    if (state[idx] == EMPTY) {
                        return -1;
                    }
                    if (state[idx] == ACTIVE && hashes[idx] == hash && keys[idx] == key) {
                        return idx;
                    }
                    if (p == probes) {
                        break;
                    }
                    idx++;
                }
                perturb >>>= PERTURB_SHIFT;
                i = (i * 5 + 1 + perturb) & maskL;
            }
        }

        boolean containsEntry(long key, long hash) {
            return lookup(key, hash) != -1;
        }

        void discardEntry(long key, long hash) {
            int idx = lookup(key, hash);
            if (idx != -1) {
                state[idx] = DUMMY;
                used--;
            }
        }

        ArrayList<Long> toList() {
            ArrayList<Long> out = new ArrayList<>();
            for (int idx = 0; idx < state.length; idx++) {
                if (state[idx] == ACTIVE) {
                    out.add(keys[idx]);
                }
            }
            return out;
        }
    }

    private static long pyHash(long v) {
        final BigInteger MOD = BigInteger.valueOf((1L << 61) - 1);
        long h = BigInteger.valueOf(v).abs().mod(MOD).longValue();
        if (v < 0) {
            h = -h;
        }
        if (h == -1) {
            h = -2;
        }
        return h;
    }

    private static PySet fromList(ArrayList<Long> list) {
        PySet s = new PySet();
        for (Long x : list) {
            s.add(x.longValue());
        }
        return s;
    }

    // CPython set_copy: merge into a fresh set.
    private static PySet copyOf(PySet other) {
        PySet so = new PySet();
        if ((long) (so.fill + other.used) * 5 >= (long) so.mask * 3) {
            so.resize((so.used + other.used) * 2);
        }
        if (so.fill == 0 && so.mask == other.mask && other.fill == other.used) {
            so.keys = other.keys.clone();
            so.hashes = other.hashes.clone();
            so.state = other.state.clone();
            so.mask = other.mask;
            so.fill = other.fill;
            so.used = other.used;
            return so;
        }
        if (so.fill == 0) {
            for (int idx = 0; idx < other.state.length; idx++) {
                if (other.state[idx] == PySet.ACTIVE) {
                    so.insertClean(other.keys[idx], other.hashes[idx]);
                }
            }
            so.fill = other.used;
            so.used = other.used;
            return so;
        }
        for (int idx = 0; idx < other.state.length; idx++) {
            if (other.state[idx] == PySet.ACTIVE) {
                so.addEntry(other.keys[idx], other.hashes[idx]);
            }
        }
        return so;
    }

    // CPython set_difference(so, other) for a set argument.
    private static PySet difference(PySet so, PySet other) {
        if ((so.used >> 2) > other.used) {
            PySet result = copyOf(so);
            for (int idx = 0; idx < other.state.length; idx++) {
                if (other.state[idx] == PySet.ACTIVE) {
                    result.discardEntry(other.keys[idx], other.hashes[idx]);
                }
            }
            return result;
        }
        PySet result = new PySet();
        for (int idx = 0; idx < so.state.length; idx++) {
            if (so.state[idx] == PySet.ACTIVE) {
                if (!other.containsEntry(so.keys[idx], so.hashes[idx])) {
                    result.addEntry(so.keys[idx], so.hashes[idx]);
                }
            }
        }
        return result;
    }

    public static ArrayList<Long> Diff(ArrayList<Long> li1, ArrayList<Long> li2) {
        PySet s1 = fromList(li1);
        PySet s2 = fromList(li2);
        ArrayList<Long> result = difference(s1, s2).toList();
        result.addAll(difference(s2, s1).toList());
        return result;
    }
}

