import java.util.stream.*;

class Solution {
    public static boolean countDivisors(long n) {
        long count = 0;
        long limit = (long) Math.sqrt((double) n) + 1;
        for (long i = 1; i <= limit; i++) {
            if (n % i == 0) {
                if (n / i == i) {
                    count += 1;
                } else {
                    count += 2;
                }
            }
        }
        return count % 2 == 0;
    }
}

