class Solution {
    public static ArrayList<Float> rgbToHsv(long r, long g, long b) {
        double rd = r / 255.0;
        double gd = g / 255.0;
        double bd = b / 255.0;
        double mx = Math.max(rd, Math.max(gd, bd));
        double mn = Math.min(rd, Math.min(gd, bd));
        double df = mx - mn;
        double h;
        if (mx == mn) {
            h = 0.0;
        } else if (mx == rd) {
            h = pymod(60.0 * ((gd - bd) / df) + 360.0, 360.0);
        } else if (mx == gd) {
            h = pymod(60.0 * ((bd - rd) / df) + 120.0, 360.0);
        } else {
            h = pymod(60.0 * ((rd - gd) / df) + 240.0, 360.0);
        }
        double s;
        if (mx == 0.0) {
            s = 0.0;
        } else {
            s = (df / mx) * 100.0;
        }
        double v = mx * 100.0;
        ArrayList<Float> res = new ArrayList<>();
        res.add((float) h);
