class Solution {
    public static String removeAllSpaces(String text) {
        // Python reference: re.sub(r'\s+', '', text)
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < text.length(); i++) {
            char c = text.charAt(i);
            if (!isPythonWhitespace(c)) {
                sb.append(c);
            }
        }
        return sb.toString();
    }

    private static boolean isPythonWhitespace(char c) {
        // Matches Python's str \s semantics (Unicode whitespace incl. \x0b, \x1c-\x1f, \x85)
        if (c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f' || c == 0x0B) return true;
        if (c >= 0x1C && c <= 0x1F) return true;
        if (c == 0x85) return true;
        return Character.getType(c) == Character.SPACE_SEPARATOR
                || Character.getType(c) == Character.LINE_SEPARATOR
                || Character.getType(c) == Character.PARAGRAPH_SEPARATOR;
    }
}

