import java.lang.reflect.*;
import java.security.*;
import java.math.*;
import java.io.*;
import java.util.stream.*;

class Solution {
    public static long maxRunUppercase(String test_str) {
        // Faithful port of the MBPP reference, including its quirky
        // "res = cnt" (not max) reset on non-uppercase characters and the
        // final trailing-run check on the last character.
        long cnt = 0;
