function sumProperDivisors(n) {
    if (n < 2) {
        return 0;
    }
    let total = 1;
    for (let i = 2; i * i <= n; i++) {
        if (n % i === 0) {
            total += i;
            const other = n / i;
            if (other !== i) {
                total += other;
            }
        }
    }
    return total;
}

function amicable_numbers_sum(limit){
    const amicables = new Set();
    for (let num = 2; num <= limit; num++) {
        if (amicables.has(num)) {
            continue;
        }
        const partner = sumProperDivisors(num);
        if (partner !== num && sumProperDivisors(partner) === num) {
            amicables.add(num);
        }
    }
    let total = 0;
    for (const value of amicables) {
        total += value;
    }
    return total;
}

