function pancake_sort(nums){
    function flip(arr, k){
        let left = 0;
        let right = k;
        while (left < right){
            const tmp = arr[left];
            arr[left] = arr[right];
            arr[right] = tmp;
            left += 1;
            right -= 1;
        }
    }
    let arr_len = nums.length;
    while (arr_len > 1){
        let mi = 0;
        for (let i = 1; i < arr_len; i++){
            if (nums[i] > nums[mi]) mi = i;
        }
        flip(nums, mi);
        flip(nums, arr_len - 1);
        arr_len -= 1;
    }
    return nums;
}

module.exports = { pancake_sort };

