    const dp = [];
    for (let i = 0; i < n; i++){
        dp.push(new Array(n).fill(0));
        dp[i][i] = 1;
    }
    for (let cl = 2; cl <= n; cl++){
        for (let i = 0; i + cl - 1 < n; i++){
            const j = i + cl - 1;
            if (str[i] === str[j] && cl === 2){
                dp[i][j] = 2;
