function rearrange_bigger(n){
    const nums = String(n).split('');
    for (let i = nums.length - 2; i >= 0; i--) {
        if (nums[i] < nums[i + 1]) {
            const z = nums.slice(i);
            const candidates = z.filter(x => x > z[0]);
            const y = candidates.reduce((a, b) => (a < b ? a : b));
            const idxInZ = z.indexOf(y);
            z.splice(idxInZ, 1);
            z.sort();
            const newTail = [y, ...z];
            nums.splice(i, nums.length - i, ...newTail);
            return parseInt(nums.join(''), 10);
