function k_smallest_pairs(nums1, nums2, k){
    const queue = [];

    function compare(a, b){
        if (a[0] !== b[0]) return a[0] - b[0];
        if (a[1] !== b[1]) return a[1] - b[1];
        return a[2] - b[2];
    }

    function push(i, j){
        if (i < nums1.length && j < nums2.length) {
            queue.push([nums1[i] + nums2[j], i, j]);
        }
    }

    function popMin(){
        let minIdx = 0;
        for (let idx = 1; idx < queue.length; idx++) {
            if (compare(queue[idx], queue[minIdx]) < 0) minIdx = idx;
        }
        const item = queue[minIdx];
        queue.splice(minIdx, 1);
        return item;
    }

    push(0, 0);
    const pairs = [];
    while (queue.length && pairs.length < k) {
        const [, i, j] = popMin();
        pairs.push([nums1[i], nums2[j]]);
        push(i, j + 1);
        if (j === 0) {
            push(i + 1, 0);
        }
    }
    return pairs;
}

module.exports = { k_smallest_pairs };

