function find_dissimilar(test_tup1, test_tup2){
    // NOTE: the Python reference returns tuple(set(test_tup1) ^ set(test_tup2)).
    // CPython set iteration order is defined by its internal open-addressing
    // hash table (not insertion order, not sorted order). We simulate that
    // table (mask=7 start, linear probing + perturbation, resize on load
    // factor) so the emitted order matches CPython for the reference's
    // small-integer test cases.
    const MINSIZE = 8;
    const LINEAR_PROBES = 9;
    const PERTURB_SHIFT = 5;

    function pyHash(x) {
        return x === -1 ? -2 : x;
    }

    class SimSet {
        constructor(mask) {
            this.mask = mask === undefined ? MINSIZE - 1 : mask;
            this.table = new Array(this.mask + 1).fill(null);
            this.fill = 0;
            this.used = 0;
        }

        *probeSeq(h) {
            const mask = this.mask;
            let i = h & mask;
            let perturb = h;
            yield i;
            for (;;) {
                if (i + LINEAR_PROBES <= mask) {
                    for (let j = 1; j <= LINEAR_PROBES; j++) {
                        yield i + j;
                    }
                }
                perturb = perturb >> PERTURB_SHIFT;
                i = (i * 5 + 1 + perturb) & mask;
                yield i;
            }
        }

        findSlot(key, h) {
            let freeslot = null;
            for (const i of this.probeSeq(h)) {
                const entry = this.table[i];
                if (entry === null) {
                    return { found: false, slot: freeslot !== null ? freeslot : i };
                }
                if (entry === 'DUMMY') {
                    if (freeslot === null) freeslot = i;
                    continue;
                }
                if (entry.hash === h && entry.key === key) {
                    return { found: true, slot: i };
                }
            }
        }

        add(key, h) {
            const { found, slot } = this.findSlot(key, h);
            if (found) return false;
            const wasEmpty = this.table[slot] === null;
            this.table[slot] = { hash: h, key: key };
            if (wasEmpty) this.fill++;
            this.used++;
            if (this.fill * 5 >= this.mask * 3) this.resize();
            return true;
        }

        discard(key, h) {
            const { found, slot } = this.findSlot(key, h);
            if (!found) return false;
            this.table[slot] = 'DUMMY';
            this.used--;
            return true;
        }

        contains(key, h) {
            return this.findSlot(key, h).found;
        }

        resize() {
            const minused = this.used <= 50000 ? this.used * 4 : this.used * 2;
            let newsize = MINSIZE;
            while (newsize <= minused) newsize <<= 1;
            const oldEntries = this.table.filter(e => e !== null && e !== 'DUMMY');
            this.mask = newsize - 1;
            this.table = new Array(newsize).fill(null);
            this.fill = 0;
            this.used = 0;
            for (const e of oldEntries) {
                const { slot } = this.findSlot(e.key, e.hash);
                this.table[slot] = e;
                this.fill++;
                this.used++;
            }
        }

        copy() {
            const s = new SimSet(this.mask);
            s.table = this.table.slice();
            s.fill = this.fill;
            s.used = this.used;
            return s;
        }

        items() {
            const res = [];
            for (const e of this.table) {
                if (e !== null && e !== 'DUMMY') res.push(e.key);
            }
            return res;
        }
    }

    function buildSet(elements) {
        const s = new SimSet();
        for (const e of elements) s.add(e, pyHash(e));
        return s;
    }

    const A = buildSet(test_tup1);
    const B = buildSet(test_tup2);
    const result = A.copy();
    for (const key of B.items()) {
        const h = pyHash(key);
        if (result.contains(key, h)) {
            result.discard(key, h);
        } else {
            result.add(key, h);
        }
    }
    return result.items();
}

