function siftDown(heap, startpos, pos){
    const newitem = heap[pos];
    while (pos > startpos) {
        const parentpos = (pos - 1) >> 1;
        const parent = heap[parentpos];
        if (newitem < parent) {
            heap[pos] = parent;
            pos = parentpos;
            continue;
        }
        break;
    }
    heap[pos] = newitem;
}

function siftUp(heap, pos){
    const endpos = heap.length;
    const startpos = pos;
    const newitem = heap[pos];
    let childpos = 2 * pos + 1;
    while (childpos < endpos) {
        const rightpos = childpos + 1;
        if (rightpos < endpos && !(heap[childpos] < heap[rightpos])) {
            childpos = rightpos;
        }
        heap[pos] = heap[childpos];
        pos = childpos;
        childpos = 2 * pos + 1;
    }
    heap[pos] = newitem;
    siftDown(heap, startpos, pos);
}

function heappush(heap, item){
    heap.push(item);
    siftDown(heap, 0, heap.length - 1);
}

function heappop(heap){
    const lastelt = heap.pop();
    if (heap.length > 0) {
        const returnitem = heap[0];
        heap[0] = lastelt;
        siftUp(heap, 0);
        return returnitem;
    }
    return lastelt;
}

function heap_sort(iterable){
    const h = [];
    for (const value of iterable) {
        heappush(h, value);
    }
    const result = [];
    const len = h.length;
    for (let i = 0; i < len; i++) {
        result.push(heappop(h));
    }
    return result;
}

