function lcs_of_three(X, Y, Z) {
    const m = X.length;
    const n = Y.length;
    const o = Z.length;
    // 3D DP table L[m+1][n+1][o+1]
    const L = [];
    for (let i = 0; i <= m; i++) {
        const layer = [];
        for (let j = 0; j <= n; j++) {
            layer.push(new Array(o + 1).fill(0));
        }
        L.push(layer);
    }
    for (let i = 1; i <= m; i++) {
        for (let j = 1; j <= n; j++) {
            for (let k = 1; k <= o; k++) {
                if (X[i - 1] === Y[j - 1] && X[i - 1] === Z[k - 1]) {
                    L[i][j][k] = L[i - 1][j - 1][k - 1] + 1;
                } else {
                    L[i][j][k] = Math.max(
                        L[i - 1][j][k],
                        L[i][j - 1][k],
                        L[i][j][k - 1]
                    );
                }
            }
        }
    }
