export function next_smallest_palindrome(num: number): number {
    // Smallest palindromic integer strictly greater than num.
    if (num < 0) {
        return 0;
    }
    const target = num + 1;
    const s = String(target);
    const n = s.length;
    const half = Math.floor(n / 2);

    const mirror = (arr: string[]): void => {
        for (let i = 0; i < half; i++) {
            arr[n - 1 - i] = arr[i];
        }
    };

    // Candidate: mirror the left half onto the right half.
    const candidate = s.split("");
    mirror(candidate);
    const candValue = Number(candidate.join(""));
    if (candValue >= target) {
        return candValue;
    }

    // Otherwise increment the middle (rightmost digit of the left half,
    // including the center digit for odd lengths), propagating carries left,
    // then mirror again.
    let i = Math.ceil(n / 2) - 1;
    while (i >= 0 && candidate[i] === "9") {
        candidate[i] = "0";
        i--;
    }
    if (i < 0) {
        // All nines in the left half (defensive; e.g. 99...9 -> 10...01).
        return Math.pow(10, n) + 1;
    }
    candidate[i] = String(Number(candidate[i]) + 1);
    mirror(candidate);
    return Number(candidate.join(""));
}

