export function eulerian_num(n: number, m: number): number {
    const memo = new Map<string, number>();
    const compute = (a: number, b: number): number => {
        if (b >= a || a === 0) {
            return 0;
        }
        if (b === 0) {
            return 1;
        }
        const key = a + "," + b;
        const cached = memo.get(key);
        if (cached !== undefined) {
            return cached;
        }
        const result =
            (a - b) * compute(a - 1, b - 1) + (b + 1) * compute(a - 1, b);
        memo.set(key, result);
        return result;
    };
    return compute(n, m);
}

