export function remove_Occ(s: string, ch: string): string {
    const first = s.indexOf(ch);
    if (first === -1) {
        return s;
    }
    let result = s.slice(0, first) + s.slice(first + ch.length);
    const last = result.lastIndexOf(ch);
    if (last !== -1) {
        result = result.slice(0, last) + result.slice(last + ch.length);
    }
    return result;
}

