function properDivisorSum(n: number): number {
    if (n <= 1) {
        return 0;
    }
    let total = 1;
    for (let i = 2; i * i <= n; i++) {
        if (n % i === 0) {
            total += i;
            const other = n / i;
            if (other !== i) {
                total += other;
            }
        }
    }
    return total;
}

export function amicable_numbers_sum(limit: number): number {
    const amicables = new Set<number>();
    for (let num = 2; num <= limit; num++) {
        if (amicables.has(num)) {
            continue;
        }
        const partner = properDivisorSum(num);
        if (partner !== num && properDivisorSum(partner) === num) {
            amicables.add(num);
            amicables.add(partner);
        }
    }
    let total = 0;
    for (const value of amicables) {
        total += value;
    }
    return total;
}

