export function magic_square_test(my_matrix: number[][]): boolean {
    const n = my_matrix.length;
    if (n === 0) {
        return true;
    }
    const sums: number[] = [];
    for (const row of my_matrix) {
        sums.push(row.reduce((acc, v) => acc + v, 0));
    }
    for (let col = 0; col < n; col++) {
        let colSum = 0;
        for (let row = 0; row < n; row++) {
            colSum += my_matrix[row][col];
        }
        sums.push(colSum);
    }
    let diag1 = 0;
    let diag2 = 0;
    for (let i = 0; i < n; i++) {
        diag1 += my_matrix[i][i];
        diag2 += my_matrix[i][n - 1 - i];
    }
    sums.push(diag1, diag2);
    return sums.every((s) => s === sums[0]);
}

