export function find_solution(a: number, b: number, n: number): [number, number] | undefined {
    if (a === 0) {
        if (b !== 0 && n % b === 0) {
            return [0, n / b];
        }
        return undefined;
    }
    let i = 0;
    while (i * a <= n) {
        if ((n - i * a) % b === 0) {
            return [i, (n - i * a) / b];
        }
        i++;
    }
    return undefined;
}

