export function get_total_number_of_sequences(m: number, n: number): number {
    const T: number[][] = [];
    for (let i = 0; i <= m; i++) {
        T.push(new Array<number>(n + 1).fill(0));
    }
    for (let i = 0; i <= m; i++) {
        for (let j = 0; j <= n; j++) {
            if (i === 0 || j === 0) {
                T[i][j] = 0;
            } else if (i < j) {
                T[i][j] = 0;
            } else if (j === 1) {
                T[i][j] = i;
            } else {
                T[i][j] = T[i - 1][j] + T[Math.floor(i / 2)][j - 1];
            }
        }
    }
    return T[m][n];
}

