export function max_sum(arr: number[]): number {
    const n = arr.length;
    const msibs = arr.slice();
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < i; j++) {
            if (arr[i] > arr[j] && msibs[i] < msibs[j] + arr[i]) {
                msibs[i] = msibs[j] + arr[i];
            }
        }
    }
    const msdbs = arr.slice();
    for (let i = 1; i <= n; i++) {
        for (let j = 1; j < i; j++) {
            if (arr[n - i] > arr[n - j] && msdbs[n - i] < msdbs[n - j] + arr[n - i]) {
                msdbs[n - i] = msdbs[n - j] + arr[n - i];
            }
        }
    }
    let result = -Infinity;
    for (let k = 0; k < n; k++) {
        result = Math.max(result, msibs[k] + msdbs[k] - arr[k]);
    }
    return result;
}

