export function count_no_of_ways(n: number, k: number): number {
    const mod = 1000000007;
    const dp: number[] = new Array(Math.max(n + 1, 3)).fill(0);
    dp[1] = k;
    dp[2] = k * k;
    for (let i = 3; i <= n; i++) {
        dp[i] = ((k - 1) * (dp[i - 1] + dp[i - 2])) % mod;
    }
    return dp[n];
}

