export function sum_of_digits(nums: any[]): number {
    let total = 0;
    const visit = (val: any): void => {
        if (Array.isArray(val)) {
            for (const v of val) visit(v);
            return;
        }
        const s = String(val);
        for (const ch of s) {
            if (ch >= "0" && ch <= "9") {
                total += Number(ch);
            }
        }
    };
    for (const n of nums) visit(n);
    return total;
}

