export function max_subarray_product(arr: number[]): number {
    let maxEndingHere = arr[0];
    let minEndingHere = arr[0];
    let maxSoFar = arr[0];
    for (let i = 1; i < arr.length; i++) {
        const n = arr[i];
        const candidates = [n, maxEndingHere * n, minEndingHere * n];
        maxEndingHere = Math.max(...candidates);
        minEndingHere = Math.min(...candidates);
        if (maxEndingHere > maxSoFar) {
            maxSoFar = maxEndingHere;
        }
    }
    return maxSoFar;
}

