export function find_remainder(arr: number[], n: number): number {
    let mul = 1;
    for (const x of arr) {
        // Python-style modulo (result has the sign of n) applied at each step
        mul = pyMod(mul * pyMod(x, n), n);
    }
    return pyMod(mul, n);
}

function pyMod(a: number, b: number): number {
    return ((a % b) + b) % b;
}

