// Faithful port of the MBPP reference:
//   def find_dissimilar(t1, t2): return tuple(set(t1) ^ set(t2))
// The output ORDER comes from CPython's set implementation, so we simulate
// CPython's open-addressing set table (setobject.c) for integer keys.

type Slot = { h: number; k: number } | 'dummy' | null;

const LINEAR_PROBES = 9;
const MINSIZE = 8;

class PySet {
    table: Slot[];
    mask: number;
    fill = 0;
    used = 0;

    constructor() {
        this.table = new Array<Slot>(MINSIZE).fill(null);
        this.mask = MINSIZE - 1;
    }

    static hash(k: number): number {
        // CPython small-int hash: hash(n) == n, except hash(-1) == -2.
        return k === -1 ? -2 : k;
    }

    private static idx(h: number, mask: number): number {
        // (size_t)hash & mask for possibly negative hash
        const m = mask + 1;
        return ((h % m) + m) % m;
    }

    addEntry(k: number, h: number): void {
        const mask = this.mask;
        let i = PySet.idx(h, mask);
        let perturb = h < 0 ? h + 18446744073709551616 : h; // size_t cast
        let freeslot = -1;

        for (;;) {
            let probes = (i + LINEAR_PROBES <= mask) ? LINEAR_PROBES : 0;
            let j = i;
            do {
                const e = this.table[j];
                if (e === null) {
                    // found unused (or reuse a previously seen dummy)
                    if (freeslot >= 0) {
                        this.table[freeslot] = { h, k };
                        this.used++;
                        return;
                    }
                    this.table[j] = { h, k };
                    this.fill++;
                    this.used++;
                    if (this.fill * 5 >= mask * 3) {
                        this.resize(this.used > 50000 ? this.used * 2 : this.used * 4);
                    }
                    return;
                } else if (e === 'dummy') {
                    freeslot = j;
                } else if (e.h === h && e.k === k) {
                    return; // already present
                }
                j++;
            } while (probes-- > 0);
            perturb = Math.floor(perturb / 32); // perturb >>= PERTURB_SHIFT (5)
            i = (i * 5 + 1 + perturb) & mask;
        }
    }

    add(k: number): void {
        this.addEntry(k, PySet.hash(k));
    }

    private lookkey(k: number, h: number): number {
        const mask = this.mask;
        let i = PySet.idx(h, mask);
        let perturb = h < 0 ? h + 18446744073709551616 : h;
        for (;;) {
            let probes = (i + LINEAR_PROBES <= mask) ? LINEAR_PROBES : 0;
            let j = i;
            do {
                const e = this.table[j];
                if (e === null) {
                    return -1; // not found
                }
                if (e !== 'dummy' && e.h === h && e.k === k) {
                    return j;
                }
                j++;
            } while (probes-- > 0);
            perturb = Math.floor(perturb / 32);
            i = (i * 5 + 1 + perturb) & mask;
        }
    }

    discardEntry(k: number, h: number): boolean {
        const j = this.lookkey(k, h);
        if (j < 0) {
            return false;
        }
        this.table[j] = 'dummy';
        this.used--;
        return true;
    }

    private insertClean(k: number, h: number): void {
        const mask = this.mask;
        let i = PySet.idx(h, mask);
        let perturb = h < 0 ? h + 18446744073709551616 : h;
        for (;;) {
            if (this.table[i] === null) {
                this.table[i] = { h, k };
                return;
            }
            if (i + LINEAR_PROBES <= mask) {
                for (let j = 1; j <= LINEAR_PROBES; j++) {
                    if (this.table[i + j] === null) {
                        this.table[i + j] = { h, k };
                        return;
                    }
                }
            }
            perturb = Math.floor(perturb / 32);
            i = (i * 5 + 1 + perturb) & mask;
        }
    }

    resize(minused: number): void {
        let newsize = MINSIZE;
        while (newsize <= minused) {
            newsize <<= 1;
        }
        const old = this.table;
        this.table = new Array<Slot>(newsize).fill(null);
        this.mask = newsize - 1;
        this.fill = this.used;
        for (const e of old) {
            if (e !== null && e !== 'dummy') {
                this.insertClean(e.k, e.h);
            }
        }
    }

    // set_merge into an empty freshly-created set (copy construction path)
    mergeFrom(other: PySet): void {
        if ((this.fill + other.used) * 5 >= this.mask * 3) {
            this.resize((this.used + other.used) * 2);
        }
        if (this.fill === 0 && this.mask === other.mask && other.fill === other.used) {
            // direct table copy, same layout
            for (let i = 0; i <= other.mask; i++) {
                const e = other.table[i];
                if (e !== null && e !== 'dummy') {
                    this.table[i] = { h: e.h, k: e.k };
                }
            }
            this.fill = other.fill;
            this.used = other.used;
            return;
        }
        if (this.fill === 0) {
            for (const e of other.entries()) {
                this.insertClean(e.k, e.h);
            }
            this.fill = other.used;
            this.used = other.used;
            return;
        }
        for (const e of other.entries()) {
            this.addEntry(e.k, e.h);
        }
    }

    entries(): { h: number; k: number }[] {
        const res: { h: number; k: number }[] = [];
        for (let i = 0; i <= this.mask; i++) {
            const e = this.table[i];
            if (e !== null && e !== 'dummy') {
                res.push(e);
            }
        }
        return res;
    }

    keys(): number[] {
        return this.entries().map((e) => e.k);
    }

    static fromIterable(items: number[]): PySet {
        const s = new PySet();
        for (const x of items) {
            s.add(x);
        }
        return s;
    }
}

export function find_dissimilar(test_tup1: [number, number, number, number], test_tup2: [number, number, number, number]): [number, number, number, number] {
    const so = PySet.fromIterable(test_tup1 as number[]);
    const otherIn = PySet.fromIterable(test_tup2 as number[]);

    // CPython set_symmetric_difference(so, other):
    //   otherset = set(other)  (fresh copy)
    //   otherset.symmetric_difference_update(so)
    //   return otherset
    const otherset = new PySet();
    otherset.mergeFrom(otherIn);

    for (const e of so.entries()) {
        if (!otherset.discardEntry(e.k, e.h)) {
            otherset.addEntry(e.k, e.h);
        }
    }

    return otherset.keys() as [number, number, number, number];
}

