export function catalan_number(num: number): number {
    const memo = new Map<number, number>();
    function cat(n: number): number {
        if (n <= 1) {
            return 1;
        }
        const cached = memo.get(n);
        if (cached !== undefined) {
            return cached;
        }
        let res = 0;
        for (let i = 0; i < n; i++) {
            res += cat(i) * cat(n - i - 1);
        }
        memo.set(n, res);
        return res;
    }
    return cat(num);
}

