function pySlice(arr: number[], start: number | undefined, stop: number | undefined): number[] {
    const len = arr.length;
    let s = start === undefined ? 0 : start;
    let e = stop === undefined ? len : stop;
    if (s < 0) {
        s = Math.max(len + s, 0);
    } else {
        s = Math.min(s, len);
    }
    if (e < 0) {
        e = Math.max(len + e, 0);
    } else {
        e = Math.min(e, len);
    }
    if (s >= e) {
        return [];
    }
    return arr.slice(s, e);
}

export function remove_kth_element(list1: number[], L: number): number[] {
    // Mirrors Python: list1[:L-1] + list1[L:]  (1-indexed k, with Python slice semantics)
    return pySlice(list1, undefined, L - 1).concat(pySlice(list1, L, undefined));
}

