export function heap_sort(iterable: number[]): number[] {
    // Mirrors Python heapq-based sort: repeatedly pop the smallest element.
    const heap: number[] = [];
    for (const value of iterable) {
        heapPush(heap, value);
    }
    const result: number[] = [];
    while (heap.length > 0) {
        result.push(heapPop(heap));
    }
    return result;
}

function heapPush(heap: number[], item: number): void {
    heap.push(item);
    let pos = heap.length - 1;
    while (pos > 0) {
        const parent = (pos - 1) >> 1;
        if (heap[pos] < heap[parent]) {
            const tmp = heap[pos];
            heap[pos] = heap[parent];
            heap[parent] = tmp;
            pos = parent;
        } else {
            break;
        }
    }
}

function heapPop(heap: number[]): number {
    const last = heap.pop() as number;
    if (heap.length === 0) {
        return last;
    }
    const top = heap[0];
    heap[0] = last;
    let pos = 0;
    const n = heap.length;
    while (true) {
        let child = 2 * pos + 1;
        if (child >= n) {
            break;
        }
        if (child + 1 < n && heap[child + 1] < heap[child]) {
            child = child + 1;
        }
        if (heap[child] < heap[pos]) {
            const tmp = heap[pos];
            heap[pos] = heap[child];
            heap[child] = tmp;
            pos = child;
        } else {
            break;
        }
    }
    return top;
}

