// Python str.islower(): at least one cased char, and no cased char is uppercase/titlecase.
function isLowerString(chars: string[]): boolean {
    let hasCased = false;
    for (const ch of chars) {
        const lower = ch.toLowerCase();
        const upper = ch.toUpperCase();
        if (lower === upper) {
            continue; // uncased character
        }
        if (ch !== lower) {
            return false; // cased but not lowercase
        }
        hasCased = true;
    }
    return hasCased;
}

