export function reverse_Array_Upto_K(input: number[], k: number): number[] {
    // Mirrors Python: input[k-1::-1] + input[k:]
    const n = input.length;
    let start = k - 1;
    if (start < 0) {
        start += n; // Python negative index semantics
    }
    start = Math.min(start, n - 1);
    const head: number[] = [];
    for (let i = start; i >= 0; i--) {
        head.push(input[i]);
    }
    let tailStart: number;
    if (k < 0) {
        tailStart = Math.max(0, n + k);
    } else {
        tailStart = Math.min(k, n);
    }
    return head.concat(input.slice(tailStart));
}

