export function left_insertion(a: number[], x: number): number {
    let lo = 0;
    let hi = a.length;
    while (lo < hi) {
        const mid = Math.floor((lo + hi) / 2);
        if (a[mid] < x) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    return lo;
}

