function pythonRound(x: number): number {
    const floor = Math.floor(x);
    const diff = x - floor;
    if (diff < 0.5) {
        return floor;
    }
    if (diff > 0.5) {
        return floor + 1;
    }
    // exactly halfway: round half to even (banker's rounding)
    return floor % 2 === 0 ? floor : floor + 1;
}

