export function rotate_right(list: number[], m: number): number[] {
    const n = list.length;
    // Python: result = list[-m:] + list[:-m]
    let tail: number[];
    let head: number[];
    if (m === 0) {
        // list[-0:] == whole list, list[:-0] == list[:0] == []
        tail = list.slice();
        head = [];
    } else {
        const cut = Math.max(n - m, 0);
        tail = list.slice(cut);
        head = list.slice(0, cut);
    }
    return tail.concat(head);
}

