export function lcs_of_three(X: string, Y: string, Z: string): number {
    const xs = Array.from(X);
    const ys = Array.from(Y);
    const zs = Array.from(Z);
    const m = xs.length;
    const n = ys.length;
    const o = zs.length;
    const L: number[][][] = [];
    for (let i = 0; i <= m; i++) {
        const layer: number[][] = [];
        for (let j = 0; j <= n; j++) {
            layer.push(new Array<number>(o + 1).fill(0));
        }
        L.push(layer);
    }
    for (let i = 1; i <= m; i++) {
        for (let j = 1; j <= n; j++) {
            for (let k = 1; k <= o; k++) {
                if (xs[i - 1] === ys[j - 1] && xs[i - 1] === zs[k - 1]) {
                    L[i][j][k] = L[i - 1][j - 1][k - 1] + 1;
                } else {
                    L[i][j][k] = Math.max(
                        L[i - 1][j][k],
                        L[i][j - 1][k],
                        L[i][j][k - 1]
                    );
                }
            }
        }
    }
    return L[m][n][o];
}

