// Python reference: list(set(li1) - set(li2)) + list(set(li2) - set(li1))
// Output ORDER comes from CPython set iteration, so we simulate
// Objects/setobject.c faithfully (open addressing, LINEAR_PROBES=9,
// perturb probing, fill*5 >= mask*3 growth, used*4 resize hint,
// set_difference's copy-and-difference-update fast path).

const PyHASH_MODULUS = (1n << 61n) - 1n;
const LINEAR_PROBES = 9n;
const PERTURB_SHIFT = 5n;

function frexp(v: number): [number, number] {
    if (v === 0 || !isFinite(v)) {
        return [v, 0];
    }
    let e = Math.ceil(Math.log2(Math.abs(v)));
    let m = v / Math.pow(2, e);
    while (Math.abs(m) >= 1) {
        m /= 2;
        e += 1;
    }
    while (Math.abs(m) < 0.5) {
        m *= 2;
        e -= 1;
    }
    return [m, e];
}

// CPython hash() for a Python number (int or float) held in a JS number.
function pyHashNumber(x: number): bigint {
    if (Number.isInteger(x)) {
        let n = BigInt(x);
        const neg = n < 0n;
        if (neg) {
            n = -n;
        }
        let h = n % PyHASH_MODULUS;
        if (neg) {
            h = -h;
        }
        if (h === -1n) {
            h = -2n;
        }
        return h;
    }
    // _Py_HashDouble for non-integral finite doubles.
    let [m, e] = frexp(x);
    let sign = 1n;
    if (m < 0) {
        sign = -1n;
        m = -m;
    }
    let hx = 0n;
    while (m !== 0) {
        hx = ((hx << 28n) & PyHASH_MODULUS) | (hx >> (61n - 28n));
        m *= 268435456.0; // 2**28
        e -= 28;
        const y = Math.floor(m);
        m -= y;
        hx += BigInt(y);
        if (hx >= PyHASH_MODULUS) {
            hx -= PyHASH_MODULUS;
        }
    }
    let eb = BigInt(e >= 0 ? e % 61 : 61 - 1 - ((-1 - e) % 61));
    hx = ((hx << eb) & PyHASH_MODULUS) | (hx >> (61n - eb));
    hx = hx * sign;
    if (hx === -1n) {
        hx = -2n;
    }
    return hx;
}

interface SetEntry {
    key: number;
    hash: bigint;
    dummy?: boolean; // deleted slot (CPython "dummy")
}

class PySetSim {
    table: (SetEntry | null)[];
    mask: bigint;
    fill: number;
    used: number;

    constructor() {
        this.table = new Array(8).fill(null);
        this.mask = 7n;
        this.fill = 0;
        this.used = 0;
    }

    static fromList(items: number[]): PySetSim {
        const s = new PySetSim();
        for (const x of items) {
            s.addWithHash(x, pyHashNumber(x));
        }
        return s;
    }

    // setobject.c set_add_entry (no dummies arise here: we never discard
    // from a set that is subsequently probed for insertion order).
    addWithHash(key: number, hash: bigint): void {
        while (true) {
            const mask = this.mask;
            let i = BigInt.asUintN(64, hash) & mask;
            let perturb = BigInt.asUintN(64, hash);
            let inserted = false;
            outer: while (true) {
                let j = i;
                let probes = i + LINEAR_PROBES <= mask ? Number(LINEAR_PROBES) : 0;
                while (true) {
                    const entry = this.table[Number(j)];
                    if (entry === null) {
                        // found_unused
                        this.table[Number(j)] = { key, hash };
                        this.fill += 1;
                        this.used += 1;
                        inserted = true;
                        break outer;
                    }
                    if (entry.hash === hash && entry.key === key) {
                        return; // found_active
                    }
                    if (probes-- === 0) {
                        break;
                    }
                    j += 1n;
                }
                perturb >>= PERTURB_SHIFT;
                i = (i * 5n + 1n + perturb) & mask;
            }
            if (inserted) {
                if (BigInt(this.fill) * 5n < this.mask * 3n) {
                    return;
                }
                this.resize(this.used > 50000 ? this.used * 2 : this.used * 4);
                return;
            }
        }
    }

    resize(minused: number): void {
        let newsize = 8n;
        while (newsize <= BigInt(minused)) {
            newsize <<= 1n;
        }
        const oldTable = this.table;
        this.table = new Array(Number(newsize)).fill(null);
        this.mask = newsize - 1n;
        this.fill = this.used;
        for (const entry of oldTable) {
            if (entry !== null && !entry.dummy) {
                this.insertClean(entry.key, entry.hash);
            }
        }
    }

    private insertClean(key: number, hash: bigint): void {
        const mask = this.mask;
        let i = BigInt.asUintN(64, hash) & mask;
        let perturb = BigInt.asUintN(64, hash);
        while (true) {
            let j = i;
            let probes = i + LINEAR_PROBES <= mask ? Number(LINEAR_PROBES) : 0;
            while (true) {
                if (this.table[Number(j)] === null) {
                    this.table[Number(j)] = { key, hash };
                    return;
                }
                if (probes-- === 0) {
                    break;
                }
                j += 1n;
            }
            perturb >>= PERTURB_SHIFT;
            i = (i * 5n + 1n + perturb) & mask;
        }
    }

    hasWithHash(key: number, hash: bigint): boolean {
        const mask = this.mask;
        let i = BigInt.asUintN(64, hash) & mask;
        let perturb = BigInt.asUintN(64, hash);
        while (true) {
            let j = i;
            let probes = i + LINEAR_PROBES <= mask ? Number(LINEAR_PROBES) : 0;
            while (true) {
                const entry = this.table[Number(j)];
                if (entry === null) {
                    return false;
                }
                if (!entry.dummy && entry.hash === hash && entry.key === key) {
                    return true;
                }
                if (probes-- === 0) {
                    break;
                }
                j += 1n;
            }
            perturb >>= PERTURB_SHIFT;
            i = (i * 5n + 1n + perturb) & mask;
        }
    }

    // setobject.c set_discard_entry: mark the slot dummy; fill unchanged.
    discardWithHash(key: number, hash: bigint): void {
        const mask = this.mask;
        let i = BigInt.asUintN(64, hash) & mask;
        let perturb = BigInt.asUintN(64, hash);
        while (true) {
            let j = i;
            let probes = i + LINEAR_PROBES <= mask ? Number(LINEAR_PROBES) : 0;
            while (true) {
                const entry = this.table[Number(j)];
                if (entry === null) {
                    return; // not present
                }
                if (!entry.dummy && entry.hash === hash && entry.key === key) {
                    entry.dummy = true;
                    this.used -= 1;
                    return;
                }
                if (probes-- === 0) {
                    break;
                }
                j += 1n;
            }
            perturb >>= PERTURB_SHIFT;
            i = (i * 5n + 1n + perturb) & mask;
        }
    }

    // setobject.c set_copy -> make_new_set(type, so) -> set_update_internal
    // -> set_merge: one big presize, then memcpy iff masks match (and the
    // source has no dummies), otherwise re-insert in the source table order.
    copy(): PySetSim {
        const result = new PySetSim();
        if ((result.fill + this.used) * 5 >= Number(result.mask) * 3) {
            result.resize((result.used + this.used) * 2);
        }
        if (result.fill === 0 && result.mask === this.mask && this.fill === this.used) {
            result.table = this.table.map((e) => (e === null ? null : { key: e.key, hash: e.hash }));
            result.fill = this.fill;
            result.used = this.used;
            return result;
        }
        for (const entry of this.entries()) {
            result.addWithHash(entry.key, entry.hash);
        }
        return result;
    }

    // setobject.c set_difference_update_internal (other is a set):
    // discard other's elements, then resize away dummies if > mask/4 of them.
    differenceUpdate(other: PySetSim): void {
        for (const entry of other.entries()) {
            this.discardWithHash(entry.key, entry.hash);
        }
        if (this.fill - this.used <= Math.floor(Number(this.mask) / 4)) {
            return;
        }
        this.resize(this.used > 50000 ? this.used * 2 : this.used * 4);
    }

    // Iteration order = table order (list(s)), skipping dummies.
    entries(): SetEntry[] {
        const out: SetEntry[] = [];
        for (const entry of this.table) {
            if (entry !== null && !entry.dummy) {
                out.push(entry);
            }
        }
        return out;
    }

    toList(): number[] {
        return this.entries().map((e) => e.key);
    }
}

// setobject.c set_difference(a, b) -> list(result)
function pySetDifferenceList(a: PySetSim, b: PySetSim): number[] {
    // Fast path (len(a) >> 2 > len(b)): copy `a`, then discard b's elements
    // in place (set_copy_and_difference).
    if (a.used >> 2 > b.used) {
        const result = a.copy();
        result.differenceUpdate(b);
        return result.toList();
    }
    // General path: build a fresh set by inserting a's survivors in order.
    const result = new PySetSim();
    for (const entry of a.entries()) {
        if (!b.hasWithHash(entry.key, entry.hash)) {
            result.addWithHash(entry.key, entry.hash);
        }
    }
    return result.toList();
}

export function Diff(li1: number[], li2: number[]): number[] {
    const s1 = PySetSim.fromList(li1);
    const s2 = PySetSim.fromList(li2);
    return [...pySetDifferenceList(s1, s2), ...pySetDifferenceList(s2, s1)];
}

