export function check_expression(exp: string): boolean {
    // Mirrors the MBPP reference: odd-length expressions are immediately unbalanced,
    // non-bracket characters are ignored.
    const chars = Array.from(exp);
    if (chars.length & 1) {
        return false;
    }
    const stack: string[] = [];
    for (const ch of chars) {
        if (ch === '(' || ch === '{' || ch === '[') {
            stack.push(ch);
        }
        if (ch === ')' || ch === '}' || ch === ']') {
            if (stack.length === 0) {
                return false;
            }
            const top = stack.pop();
            if (
                (top === '(' && ch !== ')') ||
                (top === '{' && ch !== '}') ||
                (top === '[' && ch !== ']')
            ) {
                return false;
            }
        }
    }
    return stack.length === 0;
}

