export function occurance_substring(text: string, pattern: string): [string, number, number] | undefined {
    // Python: for match in re.finditer(pattern, text): return (text[s:e], s, e)
    // Returns undefined (Python None) when there is no match.
    const s = text.indexOf(pattern);
    if (s === -1) {
        return undefined;
    }
    const e = s + pattern.length;
    return [text.slice(s, e), s, e];
}

