export function count_vowels(test_str: string): number {
    // Mirrors the MBPP reference: counts non-vowel characters that have at least
    // one vowel neighbor; interior positions first, then ONLY the first-char
    // edge check (the reference has no trailing-edge check -- load-bearing quirk:
    // count_vowels('partofthejourney') must be 8, not 9).
    const chars = Array.from(test_str);
    const isVowel = (c: string): boolean =>
        c === 'a' || c === 'e' || c === 'i' || c === 'o' || c === 'u';
    let res = 0;
    for (let idx = 1; idx < chars.length - 1; idx++) {
        if (!isVowel(chars[idx]) && (isVowel(chars[idx - 1]) || isVowel(chars[idx + 1]))) {
            res++;
        }
    }
    if (!isVowel(chars[0]) && isVowel(chars[1])) {
        res++;
    }
    return res;
}

