export function count_divisors(n: number): boolean {
    let count = 0;
    const limit = Math.floor(Math.sqrt(n)) + 2;
    for (let i = 1; i < limit; i++) {
        if (n % i === 0) {
            if (Math.floor(n / i) === i) {
                count = count + 1;
            } else {
                count = count + 2;
            }
        }
    }
    return count % 2 === 0;
}

