function pythonMod(a: number, b: number): number {
    const r = a % b;
    if (r !== 0 && (r < 0) !== (b < 0)) {
        return r + b;
    }
    return r;
}

export function rgb_to_hsv(r: number, g: number, b: number): number[] {
    const rr = r / 255.0;
    const gg = g / 255.0;
    const bb = b / 255.0;
    const mx = Math.max(rr, gg, bb);
    const mn = Math.min(rr, gg, bb);
    const df = mx - mn;
    let h = 0;
    if (mx === mn) {
        h = 0;
    } else if (mx === rr) {
        h = pythonMod(60 * ((gg - bb) / df) + 360, 360);
    } else if (mx === gg) {
        h = pythonMod(60 * ((bb - rr) / df) + 120, 360);
    } else if (mx === bb) {
        h = pythonMod(60 * ((rr - gg) / df) + 240, 360);
    }
    let s: number;
    if (mx === 0) {
        s = 0;
    } else {
        s = (df / mx) * 100;
    }
    const v = mx * 100;
    return [h, s, v];
}

