export function last(arr: number[], x: number): number {
    let lo = 0;
    let hi = arr.length - 1;
    let res = -1;
    while (lo <= hi) {
        const mid = Math.floor((lo + hi) / 2);
        if (arr[mid] > x) {
            hi = mid - 1;
        } else if (arr[mid] < x) {
            lo = mid + 1;
        } else {
            res = mid;
            lo = mid + 1;
        }
    }
    return res;
}

