export function max_run_uppercase(test_str: string): number {
    // Faithful port of the classic MBPP reference:
    // res is OVERWRITTEN with cnt on each non-uppercase char (no max taken),
    // and the trailing run only counts if the final character is uppercase.
    let cnt = 0;
    let res = 0;
    for (let idx = 0; idx < test_str.length; idx++) {
        if (isUpperChar(test_str[idx])) {
            cnt += 1;
        } else {
            res = cnt;
            cnt = 0;
        }
    }
    if (test_str.length > 0 && isUpperChar(test_str[test_str.length - 1])) {
        res = cnt;
    }
    return res;
}

