fn digits_to_value(digits: &[isize]) -> isize {
    let mut value: isize = 0;
    for &d in digits {
        value = value * 10 + d;
    }
    value
}

fn next_smallest_palindrome(num: isize) -> isize {
    // Every single-digit successor is itself a palindrome below 9.
    if num < 9 {
        return if num < 0 { 0 } else { num + 1 };
    }

    let digits: Vec<isize> = num
        .to_string()
        .bytes()
        .map(|b| (b - b'0') as isize)
        .collect();
    let len = digits.len();

    // All nines: 9 -> 11, 99 -> 101, 999 -> 1001, ...
    if digits.iter().all(|&d| d == 9) {
        let mut result: isize = 1;
        for _ in 0..len {
            result *= 10;
        }
        return result + 1;
    }

    // Candidate 1: mirror the left half onto the right half.
    let mut cand = digits.clone();
    for i in 0..len / 2 {
        cand[len - 1 - i] = cand[i];
    }
    let mirrored = digits_to_value(&cand);
    if mirrored > num {
        return mirrored;
    }

    // Otherwise increment the left half (including the middle digit) with
    // carry, then mirror again. The carry cannot run off the left end because
    // the all-nines case was handled above.
    let mid = (len - 1) / 2;
    let mut i = mid as i64;
    while i >= 0 {
        let idx = i as usize;
        if cand[idx] == 9 {
            cand[idx] = 0;
            i -= 1;
        } else {
            cand[idx] += 1;
            break;
        }
    }
    for j in 0..len / 2 {
        cand[len - 1 - j] = cand[j];
    }
    digits_to_value(&cand)
}

