fn magic_square_test(my_matrix: Vec<Vec<isize>>) -> bool {
    let n = my_matrix.len();
    if n == 0 {
        return true;
    }
    if my_matrix.iter().any(|row| row.len() != n) {
        return false;
    }
    let target: isize = my_matrix[0].iter().sum();
    for row in &my_matrix {
        if row.iter().sum::<isize>() != target {
            return false;
        }
    }
    for j in 0..n {
        let col_sum: isize = (0..n).map(|i| my_matrix[i][j]).sum();
        if col_sum != target {
            return false;
        }
    }
    let diag1: isize = (0..n).map(|i| my_matrix[i][i]).sum();
    let diag2: isize = (0..n).map(|i| my_matrix[i][n - 1 - i]).sum();
    diag1 == target && diag2 == target
}

