fn start_withp(words: Vec<String>) -> (String, String) {
    fn is_word(c: char) -> bool {
        c.is_alphanumeric() || c == '_'
    }
    for w in words {
        let chars: Vec<char> = w.chars().collect();
        let n = chars.len();
        if n == 0 || chars[0] != 'P' {
            continue;
        }
        let mut i = 1;
        while i < n && is_word(chars[i]) {
            i += 1;
        }
        if i == 1 {
            continue; // need at least one word char after the first 'P'
        }
        if i >= n {
            continue; // need a non-word separator char
        }
        let first: String = chars[0..i].iter().collect();
        let j = i + 1;
        if j >= n || chars[j] != 'P' {
            continue;
        }
        let mut k = j + 1;
        while k < n && is_word(chars[k]) {
            k += 1;
        }
        if k == j + 1 {
            continue; // need at least one word char after the second 'P'
        }
        let second: String = chars[j..k].iter().collect();
        return (first, second);
    }
    (String::new(), String::new())
}

