// Simulation of CPython's set object (Objects/setobject.c, v3.9) to reproduce
// the exact iteration order of `tuple(set(t1) ^ set(t2))` from the MBPP reference.

const PY_LINEAR_PROBES: usize = 9;

#[derive(Clone, Copy)]
enum PySlot {
    Unused,
    Dummy,
    Active(isize, i64),
}

struct PySetSim {
    table: Vec<PySlot>,
    fill: usize,
    used: usize,
    mask: usize,
}

fn py_hash_int(v: isize) -> i64 {
    const P: i128 = (1i128 << 61) - 1;
    let x = v as i128;
    let mut h = if x >= 0 {
        (x % P) as i64
    } else {
        -(((-x) % P) as i64)
    };
    if h == -1 {
        h = -2;
    }
    h
}

impl PySetSim {
    fn new() -> Self {
        PySetSim {
            table: vec![PySlot::Unused; 8],
            fill: 0,
            used: 0,
            mask: 7,
        }
    }

    // set_insert_clean: probing insert into a table known not to contain the key.
    fn insert_clean(table: &mut [PySlot], mask: usize, key: isize, hash: i64) {
        let mut perturb = hash as u64;
        let mut i = (hash as u64 as usize) & mask;
        loop {
            let probes = if i + PY_LINEAR_PROBES <= mask {
                PY_LINEAR_PROBES
            } else {
                0
            };
            for j in i..=i + probes {
                if let PySlot::Unused = table[j] {
                    table[j] = PySlot::Active(key, hash);
                    return;
                }
            }
            perturb >>= 5;
            i = i
                .wrapping_mul(5)
                .wrapping_add(1)
                .wrapping_add(perturb as usize)
                & mask;
        }
    }

    // set_table_resize
    fn resize(&mut self, minused: usize) {
        let mut newsize = 8usize;
        while newsize <= minused {
            newsize <<= 1;
        }
        if newsize == 8 && self.mask == 7 {
            // Shrinking to (or staying at) the small table while already on it.
            if self.fill == self.used {
                return; // no dummies, nothing to do
            }
            // Rebuild in place to purge dummies.
            let old = std::mem::replace(&mut self.table, vec![PySlot::Unused; 8]);
            self.fill = self.used;
            for slot in old {
                if let PySlot::Active(k, h) = slot {
                    Self::insert_clean(&mut self.table, 7, k, h);
                }
            }
            return;
        }
        let old = std::mem::replace(&mut self.table, vec![PySlot::Unused; newsize]);
        self.mask = newsize - 1;
        self.fill = self.used;
        for slot in old {
            if let PySlot::Active(k, h) = slot {
                Self::insert_clean(&mut self.table, self.mask, k, h);
            }
        }
    }

    // set_add_entry (3.9: dummies are never reused; inserts only into unused slots)
    fn add(&mut self, key: isize, hash: i64) {
        let mask = self.mask;
        let mut perturb = hash as u64;
        let mut i = (hash as u64 as usize) & mask;
        loop {
            let probes = if i + PY_LINEAR_PROBES <= mask {
                PY_LINEAR_PROBES
            } else {
                0
            };
            for j in i..=i + probes {
                match self.table[j] {
                    PySlot::Unused => {
                        // found_unused
                        self.table[j] = PySlot::Active(key, hash);
                        self.fill += 1;
                        self.used += 1;
                        if self.fill * 5 >= mask * 3 {
                            let target = if self.used > 50000 {
                                self.used * 2
                            } else {
                                self.used * 4
                            };
                            self.resize(target);
                        }
                        return;
                    }
                    PySlot::Active(k, h) => {
                        if h == hash && k == key {
                            return; // found_active
                        }
                    }
                    PySlot::Dummy => {} // hash -1 never matches; skipped
                }
            }
            perturb >>= 5;
            i = i
                .wrapping_mul(5)
                .wrapping_add(1)
                .wrapping_add(perturb as usize)
                & mask;
        }
    }

    // set_discard_entry via set_lookkey
    fn discard(&mut self, key: isize, hash: i64) -> bool {
        let mask = self.mask;
        let mut perturb = hash as u64;
        let mut i = (hash as u64 as usize) & mask;
        loop {
            let probes = if i + PY_LINEAR_PROBES <= mask {
                PY_LINEAR_PROBES
            } else {
                0
            };
            for j in i..=i + probes {
                match self.table[j] {
                    PySlot::Unused => return false,
                    PySlot::Active(k, h) => {
                        if h == hash && k == key {
                            self.table[j] = PySlot::Dummy;
                            self.used -= 1;
                            return true;
                        }
                    }
                    PySlot::Dummy => {}
                }
            }
            perturb >>= 5;
            i = i
                .wrapping_mul(5)
                .wrapping_add(1)
                .wrapping_add(perturb as usize)
                & mask;
        }
    }

    // set_merge (used by make_new_set when the source is a set)
    fn merge_from(&mut self, other: &PySetSim) {
        if other.used == 0 {
            return;
        }
        if (self.fill + other.used) * 5 >= self.mask * 3 {
            self.resize((self.used + other.used) * 2);
        }
        if self.fill == 0 && self.mask == other.mask && other.fill == other.used {
            for i in 0..=other.mask {
                if let PySlot::Active(k, h) = other.table[i] {
                    self.table[i] = PySlot::Active(k, h);
                }
            }
            self.fill = other.fill;
            self.used = other.used;
            return;
        }
        if self.fill == 0 {
            self.fill = other.used;
            self.used = other.used;
            for i in 0..=other.mask {
                if let PySlot::Active(k, h) = other.table[i] {
                    Self::insert_clean(&mut self.table, self.mask, k, h);
                }
            }
            return;
        }
        for i in 0..=other.mask {
            if let PySlot::Active(k, h) = other.table[i] {
                self.add(k, h);
            }
        }
    }

    fn from_items(items: &[isize]) -> Self {
        let mut s = PySetSim::new();
        for &v in items {
            s.add(v, py_hash_int(v));
        }
        s
    }

    fn items_in_order(&self) -> Vec<isize> {
        let mut out = Vec::new();
        for i in 0..=self.mask {
            if let PySlot::Active(k, _) = self.table[i] {
                out.push(k);
            }
        }
        out
    }
}

fn find_dissimilar(
    test_tup1: (isize, isize, isize, isize),
    test_tup2: (isize, isize, isize, isize),
) -> (isize, isize, isize, isize) {
    let s1 = PySetSim::from_items(&[test_tup1.0, test_tup1.1, test_tup1.2, test_tup1.3]);
    let s2 = PySetSim::from_items(&[test_tup2.0, test_tup2.1, test_tup2.2, test_tup2.3]);
    // CPython set.__xor__(s1, s2): build a fresh set from s2, then for every
    // entry of s1 (in table order) discard it if present, otherwise add it.
    let mut res = PySetSim::new();
    res.merge_from(&s2);
    for i in 0..=s1.mask {
        if let PySlot::Active(k, h) = s1.table[i] {
            if !res.discard(k, h) {
                res.add(k, h);
            }
        }
    }
    let mut out = res.items_in_order();
    while out.len() < 4 {
        out.push(0);
    }
    (out[0], out[1], out[2], out[3])
}

