// mbpp_592: binomial_Coeff(2*n, n-1)
fn sum_Of_product(n: isize) -> isize {
    let big_n = 2 * n;
    let k = n - 1;
    if k < 0 {
        return 0;
    }
    let mut c = vec![0isize; (k + 1) as usize];
    c[0] = 1;
    for i in 1..=big_n {
        let mut j = i.min(k);
        while j > 0 {
            c[j as usize] += c[(j - 1) as usize];
            j -= 1;
        }
    }
    c[k as usize]
}

