use std::collections::HashMap;

fn count_Substrings(s: String) -> isize {
    let n = s.len();
    let chars: Vec<char> = s.chars().collect();
    let mut mp: HashMap<i64, i64> = HashMap::new();
    mp.insert(0, 1);
    let mut count: i64 = 0;
    let mut sum: i64 = 0;
    for i in 0..n {
        sum += (chars[i] as i64) - ('0' as i64);
        let key = sum - (i as i64 + 1);
        count += *mp.get(&key).unwrap_or(&0);
        *mp.entry(key).or_insert(0) += 1;
    }
    count as isize
}

