fn find_First_Missing(array: Vec<isize>) -> isize {
    fn helper(array: &[isize], start: isize, end: isize) -> isize {
        if start > end {
            return end + 1;
        }
        if start != array[start as usize] {
            return start;
        }
        let mid = (start + end) / 2;
        if array[mid as usize] == mid {
            return helper(array, mid + 1, end);
        }
        helper(array, start, mid)
    }
    let end = array.len() as isize - 1;
    helper(&array, 0, end)
}

