fn remove_parenthesis(items: Vec<String>) -> String {
    // Python reference: for item in items: return re.sub(r" ?\([^)]+\)", "", item)
    // Only the first item is processed.
    let item = match items.first() {
        Some(s) => s.clone(),
        None => return String::new(),
    };
    let chars: Vec<char> = item.chars().collect();
    let n = chars.len();

    // Try to match the regex " ?\([^)]+\)" starting at position i.
    // Returns the end index (exclusive) of the match, if any.
    fn try_match(chars: &[char], i: usize) -> Option<usize> {
        let n = chars.len();
        let mut starts: Vec<usize> = Vec::new();
        if i < n && chars[i] == ' ' {
            starts.push(i + 1); // " ?" consumes the space (greedy first)
        }
        starts.push(i); // " ?" matches empty
        for &p in &starts {
            if p < n && chars[p] == '(' {
                let mut q = p + 1;
                let mut count = 0usize;
                while q < n && chars[q] != ')' {
                    q += 1;
                    count += 1;
                }
                if count >= 1 && q < n && chars[q] == ')' {
                    return Some(q + 1);
                }
            }
        }
        None
    }

    let mut result = String::new();
    let mut i = 0usize;
    while i < n {
        if let Some(end) = try_match(&chars, i) {
            i = end;
        } else {
            result.push(chars[i]);
            i += 1;
        }
    }
    result
}

