fn reverse_Array_Upto_K(input: Vec<isize>, k: isize) -> Vec<isize> {
    // Python reference: return input[k-1::-1] + input[k:]
    let n = input.len() as isize;
    let mut result: Vec<isize> = Vec::new();

    // input[k-1::-1]  (step -1, Python slice clamping semantics)
    let mut start = k - 1;
    if start < 0 {
        start += n;
    }
    if start >= 0 {
        if start >= n {
            start = n - 1;
        }
        let mut i = start;
        while i >= 0 {
            result.push(input[i as usize]);
            i -= 1;
        }
    }

    // input[k:]  (step 1, clamped)
    let mut s2 = k;
    if s2 < 0 {
        s2 += n;
        if s2 < 0 {
            s2 = 0;
        }
    }
    let mut i = s2;
    while i < n {
        if i >= 0 {
            result.push(input[i as usize]);
        }
        i += 1;
    }

    result
}

