fn maxAverageOfPath(cost: Vec<Vec<isize>>) -> f64 {
    let n = cost.len();
    let mut dp = vec![vec![0isize; n + 1]; n + 1];
    dp[0][0] = cost[0][0];
    for i in 1..n {
        dp[i][0] = dp[i - 1][0] + cost[i][0];
    }
    for j in 1..n {
        dp[0][j] = dp[0][j - 1] + cost[0][j];
    }
    for i in 1..n {
        for j in 1..n {
            let best = if dp[i - 1][j] > dp[i][j - 1] { dp[i - 1][j] } else { dp[i][j - 1] };
            dp[i][j] = best + cost[i][j];
        }
    }
    dp[n - 1][n - 1] as f64 / (2 * n as isize - 1) as f64
}

