fn power_base_sum(base: isize, power: isize) -> isize {
    // Compute base^power with arbitrary precision (decimal digit vector),
    // then sum the digits. Matches Python's sum of digits of pow(base, power).
    let b = base as u64;
    let mut digits: Vec<u64> = vec![1];
    let mut p = power;
    while p > 0 {
        let mut carry: u64 = 0;
        for d in digits.iter_mut() {
            let v = *d * b + carry;
            *d = v % 10;
            carry = v / 10;
        }
        while carry > 0 {
            digits.push(carry % 10);
            carry /= 10;
        }
        p -= 1;
    }
    digits.iter().sum::<u64>() as isize
}

