fn find_first_occurrence(A: Vec<isize>, x: isize) -> isize {
    let mut left: isize = 0;
    let mut right: isize = A.len() as isize - 1;
    let mut result: isize = -1;
    while left <= right {
        let mid = (left + right) / 2;
        let val = A[mid as usize];
        if x == val {
            result = mid;
            right = mid - 1;
        } else if x < val {
            right = mid - 1;
        } else {
            left = mid + 1;
        }
    }
    result
}

