        for j in 1..=n {
            for k in 1..=o {
                if x[i - 1] == y[j - 1] && x[i - 1] == z[k - 1] {
                    dp[i][j][k] = dp[i - 1][j - 1][k - 1] + 1;
                } else {
                    let a = dp[i - 1][j][k];
                    let b = dp[i][j - 1][k];
                    let c = dp[i][j][k - 1];
                    dp[i][j][k] = a.max(b).max(c);
                }
            }
        }
    }
    dp[m][n][o]
}

