// Faithful simulation of CPython 3.9 setobject.c for isize keys, so that
// list(set(li1) - set(li2)) + list(set(li2) - set(li1)) matches Python's order.

#[derive(Clone, Copy, PartialEq)]
enum DiffCpySlot {
    Unused,
    Dummy,
    Active(isize),
}

struct DiffCpySet {
    table: Vec<(i64, DiffCpySlot)>, // (hash, slot)
    mask: usize,
    fill: usize,
    used: usize,
}

fn diff_cpy_hash(v: isize) -> i64 {
    // CPython long hash: value mod (2^61 - 1), sign preserved, -1 -> -2
    let m: i128 = (1i128 << 61) - 1;
    let x = v as i128;
    let mut h: i128 = if x >= 0 { x % m } else { -((-x) % m) };
    if h == -1 {
        h = -2;
    }
    h as i64
}

impl DiffCpySet {
    const LINEAR_PROBES: usize = 9;
    const PERTURB_SHIFT: u32 = 5;
    const MINSIZE: usize = 8;

    fn new() -> Self {
        DiffCpySet {
            table: vec![(0, DiffCpySlot::Unused); Self::MINSIZE],
            mask: Self::MINSIZE - 1,
            fill: 0,
            used: 0,
        }
    }

    fn from_list(items: &[isize]) -> Self {
        let mut s = DiffCpySet::new();
        for &x in items {
            s.add_entry(x, diff_cpy_hash(x));
        }
        s
    }

    fn add_entry(&mut self, key: isize, hash: i64) {
        let mask = self.mask;
        let mut i: usize = (hash as u64 as usize) & mask;
        let mut perturb: u64 = hash as u64;
        let mut freeslot: Option<usize> = None;
        let found: usize;
        'outer: loop {
            let probes: i64 = if i + Self::LINEAR_PROBES <= mask {
                Self::LINEAR_PROBES as i64
            } else {
                0
            };
            let mut j = i;
            let mut p = probes;
            loop {
                let (h, slot) = self.table[j];
                match slot {
                    DiffCpySlot::Unused => {
                        found = j;
                        break 'outer;
                    }
                    DiffCpySlot::Active(k) => {
                        if h == hash && k == key {
                            return; // found_active
                        }
                    }
                    DiffCpySlot::Dummy => {
                        freeslot = Some(j);
                    }
                }
                j += 1;
                p -= 1;
                if p < 0 {
                    break;
                }
            }
            perturb >>= Self::PERTURB_SHIFT;
            i = (i
                .wrapping_mul(5)
                .wrapping_add(1)
                .wrapping_add(perturb as usize))
                & mask;
        }
        if let Some(fs) = freeslot {
            self.used += 1;
            self.table[fs] = (hash, DiffCpySlot::Active(key));
            return;
        }
        self.fill += 1;
        self.used += 1;
        self.table[found] = (hash, DiffCpySlot::Active(key));
        if self.fill * 5 < mask * 3 {
            return;
        }
        let minused = if self.used > 50000 {
            self.used * 2
        } else {
            self.used * 4
        };
        self.resize(minused);
    }

    fn insert_clean(&mut self, key: isize, hash: i64) {
        let mask = self.mask;
        let mut perturb: u64 = hash as u64;
        let mut i: usize = (hash as u64 as usize) & mask;
        loop {
            if let DiffCpySlot::Unused = self.table[i].1 {
                self.table[i] = (hash, DiffCpySlot::Active(key));
                return;
            }
            if i + Self::LINEAR_PROBES <= mask {
                for j in 1..=Self::LINEAR_PROBES {
                    if let DiffCpySlot::Unused = self.table[i + j].1 {
                        self.table[i + j] = (hash, DiffCpySlot::Active(key));
                        return;
                    }
                }
            }
            perturb >>= Self::PERTURB_SHIFT;
            i = (i
                .wrapping_mul(5)
                .wrapping_add(1)
                .wrapping_add(perturb as usize))
                & mask;
        }
    }

    fn resize(&mut self, minused: usize) {
        let mut newsize = Self::MINSIZE;
        while newsize <= minused {
            newsize <<= 1;
        }
        let old = std::mem::replace(&mut self.table, vec![(0, DiffCpySlot::Unused); newsize]);
        self.mask = newsize - 1;
        self.fill = self.used;
        for (h, slot) in old.into_iter() {
            if let DiffCpySlot::Active(k) = slot {
                self.insert_clean(k, h);
            }
        }
    }

    fn contains(&self, key: isize, hash: i64) -> bool {
        let mask = self.mask;
        let mut i: usize = (hash as u64 as usize) & mask;
        let mut perturb: u64 = hash as u64;
        loop {
            let probes: i64 = if i + Self::LINEAR_PROBES <= mask {
                Self::LINEAR_PROBES as i64
            } else {
                0
            };
            let mut j = i;
            let mut p = probes;
            loop {
                let (h, slot) = self.table[j];
                match slot {
                    DiffCpySlot::Unused => return false,
                    DiffCpySlot::Active(k) => {
                        if h == hash && k == key {
                            return true;
                        }
                    }
                    DiffCpySlot::Dummy => {}
                }
                j += 1;
                p -= 1;
                if p < 0 {
                    break;
                }
            }
            perturb >>= Self::PERTURB_SHIFT;
            i = (i
                .wrapping_mul(5)
                .wrapping_add(1)
                .wrapping_add(perturb as usize))
                & mask;
        }
    }

    fn discard(&mut self, key: isize, hash: i64) {
        let mask = self.mask;
        let mut i: usize = (hash as u64 as usize) & mask;
        let mut perturb: u64 = hash as u64;
        loop {
            let probes: i64 = if i + Self::LINEAR_PROBES <= mask {
                Self::LINEAR_PROBES as i64
            } else {
                0
            };
            let mut j = i;
            let mut p = probes;
            loop {
                let (h, slot) = self.table[j];
                match slot {
                    DiffCpySlot::Unused => return,
                    DiffCpySlot::Active(k) => {
                        if h == hash && k == key {
                            self.table[j] = (-1, DiffCpySlot::Dummy);
                            self.used -= 1;
                            return;
                        }
                    }
                    DiffCpySlot::Dummy => {}
                }
                j += 1;
                p -= 1;
                if p < 0 {
                    break;
                }
            }
            perturb >>= Self::PERTURB_SHIFT;
            i = (i
                .wrapping_mul(5)
                .wrapping_add(1)
                .wrapping_add(perturb as usize))
                & mask;
        }
    }

    // set_copy: make_new_set + set_merge
    fn copy(&self) -> Self {
        let mut so = DiffCpySet::new();
        if self.used == 0 {
            return so;
        }
        if (so.fill + self.used) * 5 >= so.mask * 3 {
            so.resize((so.used + self.used) * 2);
        }
        if so.fill == 0 && so.mask == self.mask && self.fill == self.used {
            so.table = self.table.clone();
            so.fill = self.fill;
            so.used = self.used;
            return so;
        }
        if so.fill == 0 {
            so.fill = self.used;
            so.used = self.used;
            for &(h, slot) in self.table.iter() {
                if let DiffCpySlot::Active(k) = slot {
                    so.insert_clean(k, h);
                }
            }
            return so;
        }
        for &(h, slot) in self.table.iter() {
            if let DiffCpySlot::Active(k) = slot {
                so.add_entry(k, h);
            }
        }
        so
    }

    // set_difference: so - other
    fn difference(&self, other: &DiffCpySet) -> DiffCpySet {
        if (self.used >> 2) > other.used {
            // set_copy_and_difference: copy, then discard members of other
            let mut result = self.copy();
            for &(h, slot) in other.table.iter() {
                if let DiffCpySlot::Active(k) = slot {
                    result.discard(k, h);
                }
            }
            return result;
        }
        let mut result = DiffCpySet::new();
        for &(h, slot) in self.table.iter() {
            if let DiffCpySlot::Active(k) = slot {
                if !other.contains(k, h) {
                    result.add_entry(k, h);
                }
            }
        }
        result
    }

    fn to_list(&self) -> Vec<isize> {
        let mut out: Vec<isize> = Vec::new();
        for &(_, slot) in self.table.iter() {
            if let DiffCpySlot::Active(k) = slot {
                out.push(k);
            }
        }
        out
    }
}

fn Diff(li1: Vec<isize>, li2: Vec<isize>) -> Vec<isize> {
    // Python: list(set(li1) - set(li2)) + list(set(li2) - set(li1))
    let s1 = DiffCpySet::from_list(&li1);
    let s2 = DiffCpySet::from_list(&li2);
    let mut out = s1.difference(&s2).to_list();
    out.extend(s2.difference(&s1).to_list());
    out
}

