fn check_expression(exp: String) -> bool {
    // Python reference: odd length -> False; classic stack matching.
    let chars: Vec<char> = exp.chars().collect();
    if chars.len() % 2 == 1 {
        return false;
    }
    let mut stack: Vec<char> = Vec::new();
    for &ch in chars.iter() {
        if ch == '(' || ch == '{' || ch == '[' {
            stack.push(ch);
        }
        if ch == ')' || ch == '}' || ch == ']' {
            match stack.pop() {
                None => return false,
                Some(top) => {
                    if (top == '(' && ch != ')')
                        || (top == '{' && ch != '}')
                        || (top == '[' && ch != ']')
                    {
                        return false;
                    }
                }
            }
        }
    }
    stack.is_empty()
}

