    if m == 0 {
        return Some((String::new(), 0, 0));
    }
    if n >= m {
        for s in 0..=(n - m) {
            if t[s..s + m] == p[..] {
                let matched: String = t[s..s + m].iter().collect();
                return Some((matched, s as isize, (s + m) as isize));
            }
        }
    }
    None
}

