            res += 1;
        }
        idx += 1;
    }
    if n >= 2 {
        if !cv_is_vowel(ch[0]) && cv_is_vowel(ch[1]) {
            res += 1;
        }
        if !cv_is_vowel(ch[n - 1]) && cv_is_vowel(ch[n - 2]) {
            res += 1;
        }
    }
