fn count_divisors(n: isize) -> bool {
    // Python: loop i in range(1, int(math.sqrt(n)) + 2); parity of divisor count
    let mut count: isize = 0;
    let upper = ((n as f64).sqrt() as isize) + 2;
    let mut i: isize = 1;
    while i < upper {
        if n % i == 0 {
            if n / i == i {
