fn rgb_to_hsv(r: isize, g: isize, b: isize) -> Vec<f64> {
    let r = r as f64 / 255.0;
    let g = g as f64 / 255.0;
    let b = b as f64 / 255.0;
    let mx = r.max(g).max(b);
    let mn = r.min(g).min(b);
    let df = mx - mn;
    let h: f64;
    if mx == mn {
        h = 0.0;
    } else if mx == r {
        h = (60.0 * ((g - b) / df) + 360.0).rem_euclid(360.0);
    } else if mx == g {
        h = (60.0 * ((b - r) / df) + 120.0).rem_euclid(360.0);
    } else {
        h = (60.0 * ((r - g) / df) + 240.0).rem_euclid(360.0);
    }
    let s = if mx == 0.0 { 0.0 } else { (df / mx) * 100.0 };
    let v = mx * 100.0;
    vec![h, s, v]
}

