fn last(arr: Vec<isize>, x: isize) -> isize {
    // Binary search for the last occurrence of x in the sorted vector.
    let mut lo: isize = 0;
    let mut hi: isize = arr.len() as isize - 1;
    let mut res: isize = -1;
    while lo <= hi {
        let mid = (lo + hi) / 2;
        if arr[mid as usize] > x {
            hi = mid - 1;
        } else if arr[mid as usize] < x {
            lo = mid + 1;
        } else {
            res = mid;
            lo = mid + 1;
        }
    }
    res
}

