fn get_Char(strr: String) -> String {
    let mut summ: i64 = 0;
    for c in strr.chars() {
        summ += (c as i64) - ('a' as i64) + 1;
    }
    if summ % 26 == 0 {
        "z".to_string()
    } else {
        let summ2 = summ % 26;
        let ch = (('a' as i64) + summ2 - 1) as u8 as char;
        ch.to_string()
    }
}
